"""Public-source city profile prose overrides. Generated by refresh script."""

from typing import Final

PUBLIC_CITY_PROFILES: Final[dict[tuple[str, str], tuple[str, str]]] = {
    ('上海市', '上海市'): ('上海市', '上海市，简称“沪”，别名“申”，是中华人民共和国直辖市，超大城市，世界一线城市，位于中国东部，长江入海口，北界长江，东濒东海，南临杭州湾，西接江苏省和浙江省，地处长江三角洲冲积平原，地势坦荡低平，属北亚热带季风气候，最大河流为黄浦江。'),
    ('云南省', '临沧市'): ('临沧市', '临沧市，旧称缅宁，是中国云南省下辖地级市，位于云南省西南部，地处东经98°40′~100°32′，北纬23°05′~25°03′之间，北回归线横穿辖区南部。东连普洱、西接保山、北靠大理，西南与缅甸交界。'),
    ('云南省', '丽江市'): ('丽江市', '丽江市，是中国云南省下辖地级市，东接四川凉山彝族自治州和攀枝花市，南连大理白族自治州剑川、鹤庆、宾川三县及楚雄彝族自治州大姚、永仁两县，西、北分别与怒江傈僳族自治州兰坪县及迪庆藏族自治州维西县毗邻。'),
    ('云南省', '保山市'): ('保山市', "保山市，是中国云南省下辖地级市，古称永昌，位于云南省西部，地处云贵高原西南部，北纬24°08'~25°51'，东经98°05′~100°02'之间。东与大理州、临沧市接壤，北与怒江州、西与德宏州毗邻，西北、正南同缅甸交界。"),
    ('云南省', '大理市'): ('大理市', '大理市，云南省大理白族自治州辖县级市，是大理白族自治州的首府，地处大理白族自治州中部，位于东经99°58′~100°27′，北纬25°25′~25°58′之间，属北亚热带高原季风气候类型，年温差小，四季不明显的气候特点。'),
    ('云南省', '德宏傣族景颇族自治州'): ('德宏傣族景颇族自治州', '德宏傣族景颇族自治州，简称“德宏州”，隶属云南省，位于云南省西部，东面与保山市相邻，而北、西、南三面都被缅甸包围，属南亚热带气候。'),
    ('云南省', '怒江傈僳族自治州'): ('怒江傈僳族自治州', '怒江傈僳族自治州，简称“怒江州”，是云南省辖民族自治州，位于云南省西北部，地处东经98°39′~99°39′，北纬25°33′~28°23′之间，北接西藏自治区林芝市察隅县，东北临迪庆藏族自治州，东靠丽江市，东南连大理白族自治州，南接保山市。'),
    ('云南省', '文山壮族苗族自治州'): ('文山壮族苗族自治州', '文山壮族苗族自治州，简称“文山州”，云南省辖自治州，位于中国西南边陲的云南省东南部，东与广西百色市接壤，南与越南社会主义共和国接界，西与红河哈尼族彝族自治州毗邻，北与曲靖市相连。'),
    ('云南省', '昆明市'): ('昆明市', '昆明市，简称“昆”，别名春城、花都，是云南省辖地级市、云南省省会、特大城市，地处中国西南部、云南省中部，位于云贵高原，总体地势由北向南呈阶梯状逐渐降低，盆地与高原错落分布。昆明市有金沙江、南盘江、红河三大流域。属亚热带高原山地季风气候，气候温和，夏无酷暑，冬无严寒。'),
    ('云南省', '昭通市'): ('昭通市', '昭通市，古称乌蒙，云南省下辖地级市，位于云南省东北部，东与贵州省接壤，西北与四川省为邻，南与曲靖市会泽县接界。全市辖1市1区9县。'),
    ('云南省', '普洱市'): ('普洱市', '普洱市，中国云南省下辖地级市，地处云南省西南部，地处北纬22°02′~24°50′，东经99°09′~102°19′之间。'),
    ('云南省', '曲靖市'): ('曲靖市', '曲靖市，是中国云南省下辖地级市，位于云南省东部，处珠江源头，云南、贵州、广西三省区交界处，东与贵州省兴义市、六盘水市毗邻，南与文山壮族苗族自治州红河哈尼族彝族自治州接壤，西接昆明市，北临昭通市，素有“滇黔锁钥”、“云南咽喉”之称，距省会昆明市120千米，地区。'),
    ('云南省', '楚雄彝族自治州'): ('楚雄彝族自治州', '楚雄彝族自治州，简称“楚雄州”，隶属云南省，位于云南省中部偏北，地跨北纬24°13′～26°30′、东经100°43′～102°32′之间，区域。'),
    ('云南省', '玉溪市'): ('玉溪市', '玉溪市，云南省辖地级市，位于云南省中部，北接昆明市，西南连普洱市，东南邻红河哈尼族彝族自治州，西北靠楚雄彝族自治州，地势西北高、东南低，山地、峡谷、高原、盆地交错分布，气候立体多样，四季如春，干湿分明。'),
    ('云南省', '红河哈尼族彝族自治州'): ('红河哈尼族彝族自治州', '红河哈尼族彝族自治州，云南省辖民族自治州，地处云南省东南部，北靠昆明市，东接文山壮族苗族自治州，西邻玉溪市，南与越南社会主义共和国接壤，属热带、亚热带立体气候。'),
    ('云南省', '西双版纳傣族自治州'): ('西双版纳傣族自治州', '西双版纳傣族自治州简称“西双版纳”，是中华人民共和国云南省下辖的自治州，位于北纬21°10′—22°40′，东经99°55′—101°50′，处于北回归线以南的热带北部边沿，东北、西北与普洱市接壤，东南与老挝相连，西南与缅甸接壤。'),
    ('云南省', '迪庆藏族自治州'): ('迪庆藏族自治州', '迪庆藏族自治州，简称“迪庆州”，云南省辖自治州，首府香格里拉市，位于云南省西北部，滇、藏、川三省区交界处，介于东经98°20′~100°19′，北纬26°52′~29°16′之间，属温带和寒温带季风气候，具有明显的低纬度高原季风气候特征，干湿分明。'),
    ('内蒙古自治区', '乌兰察布市'): ('乌兰察布市', '乌兰察布市，是中国内蒙古自治区下辖地级市，地处中国正北方、内蒙古自治区中部，是内蒙古距北京最近的一个地级市；东部与河北省接壤，东北部与锡林郭勒盟相邻，南部与山西省相连，西南部与首府呼和浩特毗连，西北部与包头相接，北部与蒙古国交界，国境线长100多千米。'),
    ('内蒙古自治区', '乌海市'): ('乌海市', '乌海市，内蒙古自治区下辖地级市，地处黄河上游，东北隔甘德尔山与鄂尔多斯搭界，南与宁夏回族自治区石嘴山市隔河相望，西接阿拉善盟，地处大陆深处，属于典型的温带大陆性气候。'),
    ('内蒙古自治区', '兴安盟'): ('兴安盟', '兴安盟，内蒙古自治区辖盟，位于内蒙古自治区东北部，地处大兴安岭向松嫩平原过渡带，东北、东南分别与黑龙江、吉林两省毗邻；南部、西部、北部分别与通辽市、锡林郭勒盟和呼伦贝尔市相连；西北部与蒙古国接壤，边境线长126千米。'),
    ('内蒙古自治区', '包头市'): ('包头市', '包头市，是中国内蒙古自治区下辖地级市，位于中国北部，内蒙古自治区西部。'),
    ('内蒙古自治区', '呼伦贝尔市'): ('呼伦贝尔市', '呼伦贝尔市（蒙古语：ᠬᠥᠯᠦᠨᠪᠦᠢᠷ），中国内蒙古自治区下辖地级市，地处内蒙古自治区东北部，以境内的呼伦湖和贝尔湖得名，南部与兴安盟相连，东部以嫩江为界与黑龙江省为邻，北和西北部以额尔古纳河为界与俄罗斯接壤，西和西南部同蒙古国交界，属亚洲中部蒙古高原的组成部分，气候分布特点以大兴安岭为分界线。'),
    ('内蒙古自治区', '呼和浩特市'): ('呼和浩特市', '呼和浩特市，简称“呼市”，旧称“归绥市”，是内蒙古自治区首府，也是内蒙古自治区的政治、经济、文化、科教和金融中心。地处内蒙古自治区中部，大青山南侧，东与乌兰察布市相邻，东南与山西省交界，南和西南与鄂尔多斯市相连，西和西北与包头市接壤。'),
    ('内蒙古自治区', '巴彦淖尔市'): ('巴彦淖尔市', "巴彦淖尔市，别名巴市、巴盟，中国内蒙古自治区辖地级市。在蒙古语中，“巴彦淖尔”意为“富饶的湖泊”。巴彦淖尔介于北纬40°13'～42°28'，东经105°12'～109°53'之间，位于内蒙古自治区西部，西、南、东分别与阿拉善盟、鄂尔多斯市、包头市为邻，北与蒙古国接壤。"),
    ('内蒙古自治区', '赤峰市'): ('赤峰市', '赤峰市，简称“赤”，原称“昭乌达盟”，中国内蒙古自治区下辖地级市、II型大城市，位于内蒙古东南部，蒙冀辽三省区交汇处，地处东北、华北地区结合部，东南与朝阳接壤，西南与承德毗邻，东部与通辽相连，西北与锡林郭勒盟交界。赤峰地貌呈三面环山、西高东低、多山多丘陵的特征，属温带半干旱大陆性季风气候区，四季分明，冬季漫长寒冷，夏季短促，雨量集中。'),
    ('内蒙古自治区', '通辽市'): ('通辽市', '通辽市，原称哲里木盟，是中国内蒙古自治区下辖地级市，地处内蒙古自治区东部，东靠吉林省四平市，西接赤峰市、锡林郭勒盟，南依辽宁省沈阳市、阜新市和铁岭市，北与兴安盟以及吉林省白城市、松原市为邻，地处中纬度，属中温带干旱和半干旱大陆性季风气候。'),
    ('内蒙古自治区', '鄂尔多斯市'): ('鄂尔多斯市', '鄂尔多斯市，中国内蒙古自治区下辖地级市，位于内蒙古自治区西南部。'),
    ('内蒙古自治区', '锡林郭勒盟'): ('锡林郭勒盟', '锡林郭勒盟，简称锡盟，内蒙古自治区辖盟，位于内蒙古自治区中部，北与蒙古国接壤，边境线长1103千米；西与乌兰察布交界；南与河北省毗邻；东与赤峰、通辽和兴安盟相连；距北京直线距离460千米。地势南高北低，东、南部多低山丘陵，盆地错落其间，为大兴安岭向西和阴山山脉向东延伸的余脉。东西长约700千米，南北宽500千米。'),
    ('内蒙古自治区', '阿拉善盟'): ('阿拉善盟', '阿拉善盟，位于内蒙古自治区最西部，东、东北与乌海、巴彦淖尔、鄂尔多斯三市相连，南、东南与宁夏回族自治区毗邻，西、西南与甘肃省接壤，北与蒙古国交界，边境线长735千米。全盟。'),
    ('北京市', '北京市'): ('北京市', '北京市，简称“京”，古称燕京、北平，是中华人民共和国首都、直辖市、国家中心城市、超大城市；中共中央、国务院批复确定的中国政治中心、文化中心、国际交往中心、科技创新中心；中国历史文化名城和古都之一、世界一线城市。'),
    ('台湾省', '台北市'): ('台北市', '台北市，是中华人民共和国台湾省省会，一线城市，处台湾岛北部的台北盆地，被新北市环绕，西界淡水河及其支流新店溪，东至南港附近，南至木栅以南丘陵区，北包大屯山东南麓。台北是台湾地区的政治、经济、文化、旅游、工业、商业与传播中心。全市下辖12个区。'),
    ('吉林省', '吉林市'): ('吉林市', '吉林市，别称“北国江城”，吉林省辖地级市。位于吉林省中部偏东，东北腹地，东接延边朝鲜族自治州，西临长春市、四平市，北与黑龙江省哈尔滨市接壤，南与白山市、通化市、辽源市毗邻，位于长白山区向松辽平原过渡地带，有“远迎长白，近绕松花”之势。属北温带大陆性季风气候，四季分明。'),
    ('吉林省', '四平市'): ('四平市', '四平市，别称“四平街、东方马德里”，吉林省辖地级市，地处吉林省西南部、松辽平原中部腹地，辽、吉、蒙三省区交界处，地势东南高，西北低，属中温带湿润季风气候区。'),
    ('吉林省', '延边朝鲜族自治州'): ('延边朝鲜族自治州', '延边朝鲜族自治州（朝鲜语：연변조선족자치주），简称延边州，吉林省辖自治州，首府延吉市，地处中国东北地区、吉林省东部、中俄朝三国交界，地形格局呈现“八山一水半草半分田”的特征，地貌呈山地、丘陵、盆地三个梯度，地处北半球中温带，属温带季风气候。'),
    ('吉林省', '松原市'): ('松原市', '松原市，别称“伯都讷、新城”，吉林省辖地级市，位于吉林省中西部、松辽盆地内部，东接长春市，南接四平市，西南达内蒙古自治区通辽市，西北临白城市，北抵黑龙江省大庆市，东北邻黑龙江省哈尔滨市，属中温带大陆性季风气候区，幅员。'),
    ('吉林省', '白城市'): ('白城市', '白城市，别称“查干浩特、白城子”，吉林省辖地级市，位于吉林省西北部，嫩江平原西部，科尔沁草原东部，吉、黑、蒙三省（区）交界处。东南部与松原市相连，西部、北部与内蒙古自治区通辽市、兴安盟接壤，东部、东北部与黑龙江省大庆市、齐齐哈尔市隔江相望。气候属温带大陆性季风气候。'),
    ('吉林省', '白山市'): ('白山市', '白山市，别称“浑江”，吉林省辖地级市，地处长白山西侧，东与延边朝鲜族自治州相邻，西与通化市接壤，北与吉林市毗连，南与朝鲜民主主义人民共和国隔鸭绿江相望，地处长白山腹地，龙岗山脉和老岭山脉斜贯全境，属北温带大陆性季风气候。'),
    ('吉林省', '辽源市'): ('辽源市', '辽源市，吉林省辖地级市，位于吉林省中南部，地处东辽河、辉发河上游，因东辽河发源于此而得名。地处长白山区向松辽平原的过渡地带，以丘陵为主，间有少量低山，属低山丘陵区，地理概貌为“五山一水四分田”，属半湿润温带大陆性季风气候。'),
    ('吉林省', '通化市'): ('通化市', '通化市，吉林省辖地级市，别称北国山城，位于吉林省东南部，东接白山市，西与本溪市、抚顺市、丹东市相邻，南与朝鲜民主主义人民共和国的慈江道隔鸭绿江相望，北连辽源市和吉林市，三分之二以上。'),
    ('吉林省', '长春市'): ('长春市', '长春市，简称长，别称北国春城，古称喜都、茶啊冲，吉林省辖地级市、省会，副省级市、哈长城市群核心城市、长春都市圈核心城市，地处中国东北地区，位于东北的地理中心，市域地形以平原为主。'),
    ('四川省', '乐山市'): ('乐山市', '乐山市，古称嘉州、嘉定州，四川省辖地级市，位于四川中部，四川盆地西南部，北与眉山市接壤，东与自贡市、宜宾市毗邻，南与凉山州相接，西与雅安市连界。地势西南高，东北低，属中亚热带气候带。'),
    ('四川省', '内江市'): ('内江市', '内江市，古称汉安、中江，别称甜城，四川省辖地级市，方言为内江话，位于四川盆地东南部、沱江下游中段，位居重庆、成都两大城市中心，素有川南咽喉、巴蜀要塞、成渝之心之称。是国家重点交通枢纽之一、一带一路重要交汇点、四川第二大交通枢纽和西南陆路交通交接点。'),
    ('四川省', '凉山彝族自治州'): ('凉山彝族自治州', '凉山彝族自治州，四川省辖自治州，简称“凉山州”，位于四川省西南部，北起大渡河与雅安市、甘孜州接壤，南至金沙江与云南省相望，东临云南省昭通市和四川省宜宾市、乐山市，西连甘孜州，属亚热带季风气候区，地质构造复杂，地貌类型齐全，有平原、盆地、丘陵、山地、高原等，幅员6.04万平方千米。'),
    ('四川省', '南充市'): ('南充市', '南充市，别称果城、绸都、果州，四川省辖地级市，位于四川省东北部、嘉陵江中游，幅员。'),
    ('四川省', '宜宾市'): ('宜宾市', '宜宾市，四川省辖地级市，地处云贵川三省结合部，金沙江、岷江、长江三江交汇处，地形整体西南高、东北低，属中亚热带季风湿润气候。'),
    ('四川省', '巴中市'): ('巴中市', '巴中市，四川省辖地级市，别称巴城，位于四川盆地东北部，地处大巴山系米仓山南麓，秦岭—淮河一线南，东邻达州市，南接南充市，西抵广元市，北接陕西省汉中市。'),
    ('四川省', '广元市'): ('广元市', '广元市，古称利州，四川省辖地级市，位于四川省北部，北与甘肃省、陕西省交界；南与南充市为邻；西与绵阳市相连；东与巴中市接壤；处于四川盆地北部边缘，山地向盆地过渡地带，属于亚热带湿润季风气候，是嘉陵江上游重要生态屏障，为川陕甘结合部区域中心城市，中国十佳宜居城市，全国旅游标准化示范市，全国康养十强市。'),
    ('四川省', '广安市'): ('广安市', '广安市，古称賨城，四川省辖地级市，位于四川省东部，地处亚热带湿润季风气候区，四季分明，气候温暖，雨量充沛，境内嘉陵江、渠江曲折回环，华蓥山、铜锣山、明月山平行分布于市境东部。'),
    ('四川省', '德阳市'): ('德阳市', '德阳市，别称“旌城”，四川省辖地级市，位于成都平原东北部，地处龙门山脉向四川盆地过渡地带；西北部为山地垂直气候，东南部为亚热带湿润季风气候。'),
    ('四川省', '成都市'): ('成都市', '成都市，简称“蓉”，别称蓉城、锦城，四川省辖地级市、省会、副省级市、超大城市、成都都市圈核心城市，地处中国西南地区、四川盆地西部、青藏高原东缘，成都平原腹心，属亚热带季风气候，热量充足，雨量丰富，四季分明。'),
    ('四川省', '攀枝花市'): ('攀枝花市', '攀枝花市，四川省辖地级市，别称渡口、钢城，地处中国西南川滇结合部，位于四川省最南端，东、北面与四川省凉山彝族自治州的会理、德昌、盐源3县接壤，西、南面与云南省的宁蒗、华坪、永仁3县交界，地处攀西裂谷中南段，属浸蚀、剥蚀中山丘陵、山原峡谷地貌，夏季长，四季不分明，而旱、雨季分明。'),
    ('四川省', '泸州市'): ('泸州市', '泸州市，四川省辖地级市，古称“江阳”，别称酒城、江城，地处四川省东南部、云贵川渝结合部，长江、沱江、赤水河在境内交汇，东与重庆市和贵州省接壤，南与贵州省连界，西与云南省和四川省宜宾市、自贡市相连，北接四川省内江市和重庆市，行政区域。'),
    ('四川省', '甘孜藏族自治州'): ('甘孜藏族自治州', '甘孜藏族自治州，俗称康巴地区或康区，是中华人民共和国四川省下辖自治州，位于四川省西部，东邻四川省雅安和阿坝藏族羌族自治州，南连四川省凉山彝族自治州和云南省迪庆藏族自治州，西沿金沙江和西藏自治区昌都相邻，北接青海省玉树藏族自治州和果洛藏族自治州。'),
    ('四川省', '眉山市'): ('眉山市', '眉山市，古称眉州，四川省辖地级市。地处成都平原南部，北接省会成都市，南连乐山市，东邻内江市、资阳市、自贡市，西接雅安市。'),
    ('四川省', '绵阳市'): ('绵阳市', '绵阳市，简称“绵”，别称绵州、涪城，四川省辖地级市，省域副中心城市，Ⅱ型大城市，三线城市，是中国唯一科技城，中国野生大熊猫第一市，位于四川盆地西北部，涪江中上游地带。东邻广元市和南充市，南接遂宁市，西接德阳市，西北与阿坝藏族羌族自治州、甘肃省陇南市接壤。'),
    ('四川省', '自贡市'): ('自贡市', '自贡市，四川省辖地级市，位于四川盆地南部；东邻隆昌市、泸县，南界泸州市江阳区、宜宾市南溪区、翠屏区、叙州区、江安县，西与犍为县、井研县毗邻，北靠仁寿县、内江市市中区、东兴区、威远县；地势西北部高、东南部低；属亚热带季风性湿润气候，冬暖、夏热、春早、秋短。'),
    ('四川省', '资阳市'): ('资阳市', '资阳市，别称西部车城，四川省辖地级市，位于四川盆地中西部，地跨东经104°12′~105°45′，北纬29°40′~30°39′。'),
    ('四川省', '达州市'): ('达州市', '达州市，四川省辖地级市，965年北宋时期改通州为达州而得名，处于四川省东北部，大巴山南麓，北高南低，由东北向西南倾斜，山、丘间分布宽缓谷地及缓丘平坝，地貌复杂多样，石灰岩广布，喀斯特地貌发育，属亚热带季风气候，气候温和，四季分明。'),
    ('四川省', '遂宁市'): ('遂宁市', '遂宁市，别称斗城、遂州，四川省辖地级市。位于四川盆地中部，涪江中游，与重庆市、成都市呈等距三角；是成渝经济区区域性中心城市，四川省现代产业基地，以“养心”文化为特色的现代生态花园城市。'),
    ('四川省', '阿坝藏族羌族自治州'): ('阿坝藏族羌族自治州', '阿坝藏族羌族自治州（藏语：རྔ་བ་བོད་རིགས་ཆའང་རིགས་རང་སྐྱོང་ཁུལ、），简称阿坝州，又名阿坝，四川省辖自治州，位于四川省西北部，青藏高原东南边缘，与成都平原接壤，属于典型高原地形，海拔较高，北、西北部与甘肃省和青海省交界，东、东南部与绵阳、德阳和成都相邻，南、西南部与雅安市毗连，西与甘孜州相接，平均海拔超过3000米，气候垂直变化明显。'),
    ('四川省', '雅安市'): ('雅安市', '雅安市，别称雨城，四川省地级市，位于四川盆地西缘、邛崃山东麓，东靠成都市、西连甘孜藏族自治州、南接凉山彝族自治州、北接阿坝藏族羌族自治州，属四川盆地西缘山地，跨四川盆地和青藏高原两大地形区，属亚热带季风性湿润气候。'),
    ('天津市', '天津市'): ('天津市', '天津市，简称“津”，是中华人民共和国直辖市、国家中心城市、超大城市，地处中国北部，华北平原东北部，海河流域下游，东临渤海，北依燕山，西靠首都北京市，其余均与河北省相邻，属暖温带半湿润季风性气候，四季分明。'),
    ('宁夏回族自治区', '中卫市'): ('中卫市', '中卫市，简称“卫”，中国宁夏回族自治区下辖地级市，位于宁夏中西部、黄河前套之首，地处宁夏平原向黄土高原的过渡带，是宁夏回族自治区、内蒙古自治区和甘肃省交界地带。'),
    ('宁夏回族自治区', '吴忠市'): ('吴忠市', '吴忠市，宁夏回族自治区辖地级市。被评为中国优秀生态旅游城市、国家园林城市、国家卫生城市、全国双拥模范城市、全国民族团结进步活动创建示范市、中国十佳绿色城市等。位于宁夏回族自治区中部，原为古灵州城和金积县驻地，地处宁夏平原腹地，地势南高北低，属中温带干旱、半干旱气候地区。'),
    ('宁夏回族自治区', '固原市'): ('固原市', '固原，简称“固”，古称大原、高平、萧关、原州，宁夏回族自治区辖地级市。位于宁夏回族自治区南部六盘山区，呈南高北低之势，东与甘肃庆阳市、平凉市为邻，南与平凉市相连，西与白银市交界，北与宁夏中卫市、吴忠市接壤，是典型的大陆性气候。'),
    ('宁夏回族自治区', '石嘴山市'): ('石嘴山市', '石嘴山市，宁夏回族自治区辖地级市，位居自治区最北端，东临鄂尔多斯市台地，西踞银川平原北部，黄河穿东过，西依贺兰山，湖泊星罗棋布，为典型的温带大陆性气候。'),
    ('宁夏回族自治区', '银川市'): ('银川市', '银川市，是宁夏回族自治区辖地级市、首府，简称“银”，古称“兴庆府”，别称“凤凰城”，地处中国西北地区、宁夏平原中部。地形分为山地和平原两大部分，西部、南部较高，北部、东部较低，属典型的中温带大陆性气候，气候干燥，蒸发强烈。'),
    ('安徽省', '亳州市'): ('亳州市', '亳州，古称亳，别称谯城。安徽省辖地级市，位于安徽省西北部，地处华北平原南端，为皖、豫两省交界，地貌呈东南、西北向斜长形，南北长约150公里，东西宽约90公里，西北与河南省接壤，西南与阜阳市毗连，东与淮北市、蚌埠市相倚，东南与淮南市为邻。辖涡阳县、蒙城县、利辛县和谯城区。行政区域。'),
    ('安徽省', '六安市'): ('六安市', '六安市，安徽省辖地级市，别称“皋城、皖西”，位于安徽省西部，大别山北麓，长江三角洲西翼，地势西南高峻，东北低平，呈梯形分布，属于北亚热带向暖温带转换的过渡带。'),
    ('安徽省', '合肥市'): ('合肥市', '合肥市，简称“合”，古称庐州、庐阳，是安徽省辖地级市、省会、特大城市、合肥都市圈核心城市，地处中国华东地区、安徽省中部、长江三角洲西翼，环抱巢湖，属亚热带季风性湿润气候，季风明显，四季分明，市境有丘陵岗地、低山残丘、低洼平原三种地貌，以丘陵岗地为主。'),
    ('安徽省', '安庆市'): ('安庆市', '安庆市，别名宜城，安徽省辖地级市，位于安徽省西南部，地处长江下游北岸，皖河入江处，西接湖北省，南邻江西省，西北靠大别山主峰，东南倚黄山余脉。'),
    ('安徽省', '宣城市'): ('宣城市', '宣城市，简称“宣”，古称宣州，是安徽省辖地级市，位于安徽省东南部，长江下游南岸，东邻浙江省杭州市、湖州市，北连马鞍山市和江苏省南京市、常州市、无锡市，西接池州市、芜湖市，南邻黄山市，地处皖南山区与沿江平原结合地带，属北亚热带湿润季风气候，四季分明，雨量充沛。'),
    ('安徽省', '宿州市'): ('宿州市', '宿州市，简称宿，别称宿城、蕲城、云都、符离，安徽省辖地级市，位于安徽省东北部，皖、苏、鲁、豫四省交界处，东、东北与宿迁和徐州接壤，南临蚌埠，西至西北与淮北、商丘和菏泽相邻。'),
    ('安徽省', '池州市'): ('池州市', '池州市，安徽省辖地级市，地处安徽省西南部，长江下游南岸，是长江经济带重要节点城市、长三角城市群中心区27个城市之一，皖江城市带承接产业转移示范区重要成员。'),
    ('安徽省', '淮北市'): ('淮北市', '淮北市，别称“相城”，安徽省辖地级市，地处安徽省北部，地势自西北向东南微倾，属暖温带半湿润季风气候区。'),
    ('安徽省', '淮南市'): ('淮南市', '淮南市，古称州来、寿春、下蔡，安徽省辖地级市，Ⅱ型大城市，地处安徽中北部，长江三角洲腹地，淮河之滨，东与滁州市毗邻，东南与合肥市接壤，西南与六安市相连，西与阜阳市相接，北与亳州市、蚌埠市交界，地处亚热带和暖温带的过渡地带。'),
    ('安徽省', '滁州市'): ('滁州市', '滁州市，古称“涂中”“清流”“新昌”，安徽省辖地级市，位于安徽省东部，市境东部与江苏省接壤，自南向北与南京市、扬州市、淮安市、宿迁市为邻；西部自北向南与安徽省蚌埠市、淮南市、合肥市、马鞍山市相依。'),
    ('安徽省', '芜湖市'): ('芜湖市', '芜湖市，安徽省辖地级市，古称“鸠兹”，又称“江城”，位于安徽省东南部，长江下游，地处长江下游平原，由阶地和河漫滩构成的平原为主，平原上分布着零星的低丘和残丘，属亚热带湿润季风气候，光照充足，雨量充沛，四季分明。'),
    ('安徽省', '蚌埠市'): ('蚌埠市', '蚌埠市，别称“珠城”，安徽省辖地级市，地处安徽省东北部，淮河中游，位于中国南北地理分界线秦岭—淮河一线，黄淮海平原与江淮丘陵的过渡地带，属北亚热带湿润季风气候与南温带半湿润季风气候区的过渡带。'),
    ('安徽省', '铜陵市'): ('铜陵市', '铜陵市，简称“铜”，别名铜都，古称定陵、义安，安徽省辖地级市，位于安徽中南部、长江下游，东与芜湖市繁昌区、南陵县接壤，南与池州市贵池区、青阳县交界，西与安庆市宜秀区、迎江区、桐城市毗邻，北与合肥市庐江县、芜湖市无为市相邻。'),
    ('安徽省', '阜阳市'): ('阜阳市', '阜阳市，安徽省辖地级市，简称阜，西周时，境内建胡国，古称汝阴、顺昌、颍州，地处黄淮海平原南端，淮北平原西部，安徽省西北部。'),
    ('安徽省', '马鞍山市'): ('马鞍山市', '马鞍山市，安徽省辖地级市，地处安徽省东部，长江下游，东邻南京市，北接滁州市，西毗合肥市，南邻芜湖市，东南连芜湖市、宣城市。'),
    ('安徽省', '黄山市'): ('黄山市', '黄山市，简称“黄”或“徽”，安徽省辖地级市，位于安徽省最南端，皖、浙、赣三省交界处。'),
    ('山东省', '东营市'): ('东营市', '东营市，山东省辖地级市，别称油城、东方湿地之城、黄河水城，位于山东省北部，东、北临渤海，西与滨州市毗邻，南与淄博市、潍坊市接壤，地势沿黄河走向自西南向东北倾斜，属暖温带大陆性季风气候，基本气候特征为冬寒夏热，四季分明。'),
    ('山东省', '临沂市'): ('临沂市', '临沂市，山东省辖地级市，位于山东省东南部，地跨北纬34°22′～36°13′，东经117°24′～119°11′之间，属温带季风气候，四季分明，雨热同季，地势自北而南有沂山、蒙山、尼山3条主要山脉延伸，控制着沂沭河上游及其支流的流向，向南构成的扇状临郯苍平原是山东三大平原之一。'),
    ('山东省', '威海市'): ('威海市', '威海市，山东省辖地级市，地处中华人民共和国华东地区、山东半岛东端，位于北纬36°41′—37°35′，东经121°11′—122°42′之间，属北温带季风型大陆性气候，四季变化和季风进退都较明显。'),
    ('山东省', '德州市'): ('德州市', '德州市，简称“德”，古称安德，山东省辖地级市，地处山东省西北部、黄河下游冲积平原，北临河北省沧州市，南接济南市、聊城市，西邻河北省衡水市，东连滨州市，地形西南高、东北低，季风影响显著，四季分明。'),
    ('山东省', '日照市'): ('日照市', '日照市，山东省辖地级市，位于山东省东南部黄海之滨，东隔黄海与日本、韩国相望，西靠临沂市，北接青岛市、潍坊市，南临江苏省连云港市，地势中部高四周低，略向东南倾斜，属暖温带半湿润季风区温带季风气候。'),
    ('山东省', '枣庄市'): ('枣庄市', '枣庄市，山东省辖地级市，三线城市。位于山东省南部，东与临沂市平邑县、费县、兰陵县接壤，南与江苏省徐州市的铜山区、贾汪区、邳州市为邻，西濒微山湖，北与济宁市的邹城市毗连。'),
    ('山东省', '泰安市'): ('泰安市', '泰安市，山东省辖地级市，II型大城市，位于山东省中部，北以泰山与济南市为界，南与济宁市相连，西隔黄河与聊城市及河南省濮阳市相望，东与济南市、淄博市、临沂市相邻。'),
    ('山东省', '济南市'): ('济南市', '济南市，简称“济”，别称“泉城”，是山东省辖地级市、省会、副省级市、特大城市，济南都市圈核心城市、位于山东省中部，南依泰山，北跨黄河，地处鲁中南低山丘陵与鲁西北冲积平原的交接带上，地势南高北低，属于暖温带大陆性季风气候区，四季分明，日照充分。济南市境内泉群众多、水量丰沛，被称为的天然岩溶泉水博物馆。'),
    ('山东省', '济宁市'): ('济宁市', '济宁市，山东省辖地级市，别名运河之都，古称济州府，Ⅱ型大城市，三线城市，位于山东省西南部，东邻临沂市，西与菏泽市接壤，南靠枣庄市和徐州市，北与泰安市交界，地形以平原洼地为主，地势东高西低，属暖温带季风气候，四季分明。'),
    ('山东省', '淄博市'): ('淄博市', '淄博市，简称“淄”，齐国故都，山东省辖地级市，Ⅱ型大城市，国务院批复确定的山东区域性中心城市、现代工业城市，重要的石油化工基地。淄博地处中国华东地区、山东省中部，南接临沂，北接东营、滨州，东接潍坊，西接济南，位于黄河三角洲高效生态经济区、山东半岛蓝色经济区两大国家战略经济区与济南都市圈交汇处，是山东半岛城市群核心城市之一，三线城市。'),
    ('山东省', '滨州市'): ('滨州市', '滨州市，山东省辖地级市，位于山东省北部、华北平原东部、黄河三角洲腹地，地处环渤海经济圈、济南都市圈“两区两圈”叠加地带，地势南高北低，大致上由西南向东北倾斜，为温带季风气候特征。'),
    ('山东省', '潍坊市'): ('潍坊市', '潍坊市，古称潍州、潍县，山东省辖地级市，Ⅱ型大城市、国家历史文化名城，位于山东省中部、山东半岛西部，东与青岛、烟台连接，西邻淄博、东营，南连临沂、日照，北濒渤海莱州湾，属暖温带季风型半湿润大陆性气候，地貌自北向南由低到高。'),
    ('山东省', '烟台市'): ('烟台市', '烟台市，山东省辖地级市，地处山东半岛东北部，东连威海市，西接潍坊市，西南与青岛市毗邻，北濒渤海、黄海，与辽东半岛对峙，并与大连市隔海相望，地形为低山丘陵区，属于暖温带大陆性季风气候。'),
    ('山东省', '聊城市'): ('聊城市', '聊城市，古称东昌，山东省地级市，位于山东省西部，冀鲁豫三省交界处，西部靠漳卫河，南部和东南部与河南省及山东省的济宁市、泰安市、济南市为邻，北部和东北部与德州市接壤。'),
    ('山东省', '菏泽市'): ('菏泽市', '菏泽市，中国牡丹之都，山东省辖地级市，地处鲁苏豫皖四省交界地区，东与济宁市相邻，东南与江苏省徐州市、安徽省宿州市接壤，南与河南省商丘市相连，西与河南省开封市、新乡市毗邻，北接河南省濮阳市。'),
    ('山东省', '青岛市'): ('青岛市', '青岛市，山东省辖地级市，简称“青”，别名“岛城”“琴岛”，为副省级市、计划单列市、青岛都市圈核心城市，地处山东半岛南部，东、南濒临黄海。属温带季风气候，市区由于海洋环境的直接调节，具有显著的海洋性气候特点。地势东高西低，南北两侧隆起，中间低凹。'),
    ('山西省', '临汾市'): ('临汾市', '临汾市，别称平阳、卧牛城、花果城，山西省辖地级市，位于山西西南部，东倚太岳，与长治、晋城为邻；西临黄河，与陕西延安、渭南隔河相望，北起韩信岭，与晋中、吕梁毗连；南与运城接壤，地处半干旱、半湿润季风气候区，属温带大陆性季风气候。'),
    ('山西省', '吕梁市'): ('吕梁市', "吕梁市，中国山西省下辖地级市，位于山西省中部西侧，地跨北纬36°43'~38°43'，东经110°22'~112°19'，因吕梁山脉纵贯全境而得名，东部紧邻太原市、晋中市，西隔黄河与陕西省相望，南部、北部分别与临汾市、忻州市接壤。"),
    ('山西省', '大同市'): ('大同市', '大同市，古称云中、平城、云州，别称中国煤都。中国山西省下辖地级市，Ⅱ型大城市，国务院批复确定的中国晋冀蒙交界地区中心城市之一和重要的综合能源基地。'),
    ('山西省', '太原市'): ('太原市', '太原市，简称“并”，古称晋阳，别称并州、龙城。山西省下辖地级市、省会、Ⅰ型大城市，位于山西省中部、晋中盆地北端，东、西、北三面群山合抱，中南部为汾河河谷平原，整个地势北高南低，属于暖温带大陆性季风气候，冬寒夏热、春秋短促、昼夜温差大、降水少且集中。'),
    ('山西省', '忻州市'): ('忻州市', '忻州市，山西省辖地级市，位于山西省中北部，北隔长城揽云朔，南界石岭通太原，西带黄河望陕蒙，东临太行连京冀。'),
    ('山西省', '晋中市'): ('晋中市', '晋中市，山西省下辖地级市，位于山西省中部，东依太行山，西临汾河，北与省会太原市毗邻，南与长治市、临汾市相交，东北与阳泉市相连，西南与吕梁市接壤。'),
    ('山西省', '晋城市'): ('晋城市', '晋城市，中国山西省下辖地级市，古称建兴、泽州、泽州府。位于山西省东南部，全境居于晋城盆地，四周群山环绕，中部相对平坦，丹河与沁河纵流全市，因春秋末年迁晋静公到此而得名。'),
    ('山西省', '朔州市'): ('朔州市', '朔州市，山西省辖地级市，别称朔、马邑，位于山西省北部，桑干河上游，西北毗邻内蒙古自治区，南扼雁门关隘，地貌轮廓总体上是北、西、南三面环山，山势较高，中间是桑干河域冲积平原，相对较低，属温带大陆性季风气候。'),
    ('山西省', '运城市'): ('运城市', '运城市，古称“河东”，因曾作为“盐运之城”得名，山西省辖地级市。位于山西省南部的晋南盆地，地处黄河北干流中游以东，华北平原的丘陵区，黄土高原东沿第一台阶。北起吕梁山脉南麓与临汾市接壤，东界中条山与晋城市毗邻，西、南隔黄河分别与陕西、河南两省相望。'),
    ('山西省', '长治市'): ('长治市', '长治市，古称上党、潞州、潞安府等，是中国山西省下辖地级市，省域副中心城市。地处晋东南，晋冀豫三省交界，位于上党盆地中。'),
    ('山西省', '阳泉市'): ('阳泉市', '阳泉市，中国山西省下辖地级市，古称“漾泉”，别称山城、中共第一城，位于山西省中东部，北与忻州市毗邻，东隔太行山与河北省石家庄市相望，西接太原市，南邻晋中市，地处黄土高原东缘，属于山西东部山地，境内地貌以山地为主，其余为丘陵和平原；属暖温带半湿润大陆性季风气候区。'),
    ('广东省', '东莞市'): ('东莞市', '东莞市，初名宝安县。中国广东省辖地级市，八九十年代为广东四小虎之一。现为国务院批复确定的粤港澳大湾区重要的节点城市，深圳都市圈城市之一；是全国先进制造业基地、国际科技创新中心承载地，拥有OPPO、vivo等全球独角兽企业，并建有中国散裂中子源、先进阿秒激光设施等国家重大科技基础设施。位于广东省中南部，珠江口东岸，东江下游的珠江三角洲，东与惠州市惠阳区接壤，西与广州市番...。'),
    ('广东省', '中山市'): ('中山市', '中山市，古称“香山”，是中华人民共和国广东省下辖地级市，位于广东省中南部，西江、北江下游出海处。八九十年代为广东四小虎之一。是珠三角中心城市之一、粤港澳大湾区重要节点城市、珠江口西岸都市圈城市之一。是国家历史文化名城、粤港澳大湾区重要一极、大湾区西岸枢纽城市与创新高地、国家自主创新型制造业城市、全国文明城市。中山市北接广州市南沙区和佛山市顺德区，西邻江门市区、新会区...。'),
    ('广东省', '云浮市'): ('云浮市', '云浮市，广东省辖地级市，地处广东省中西部，西江中游南岸。'),
    ('广东省', '佛山市'): ('佛山市', '佛山市，简称“禅”，广东省辖地级市、特大城市，地处广东省中部、珠江三角洲平原腹地，东倚广州市，西靠肇庆市，南邻江门市、中山市，北接清远市，邻近深圳市和香港特别行政区、澳门特别行政区，属南亚热带季风性湿润气候，气候温和，雨量充沛。'),
    ('广东省', '广州市'): ('广州市', '广州市，简称“穗”，别称羊城、花城、五羊城，是广东省辖地级市、省会、副省级市、国家中心城市、超大城市、世界一线城市，地处广东省中南部，珠江三角洲北缘，面朝南海，毗邻港澳，广州市地形属丘陵地区，地势东北高、西南低，境内海洋性气候特征显著。'),
    ('广东省', '惠州市'): ('惠州市', '惠州市，别称鹅城，中华人民共和国广东省下辖地级市，Ⅱ型大城市，国务院批复确定的珠江三角洲地区中心城市之一，粤港澳大湾区重要节点城市。'),
    ('广东省', '揭阳市'): ('揭阳市', '揭阳市，广东省辖地级市，是著名的华侨之乡，位于广东省东南部，粤港澳大湾区与海西经济区的地理轴线中心。下辖普宁县级市和4个区县：榕城、揭东、揭西、惠来。'),
    ('广东省', '梅州市'): ('梅州市', '梅州市，广东省辖地级市，位于广东省东北部，地处闽、粤、赣三省交界。'),
    ('广东省', '汕头市'): ('汕头市', '汕头市，简称“汕”，别称鮀城、鮀岛，广东省辖地级市，省域副中心城市，经济特区，位于广东省东部，北邻潮州市、揭阳市，南临南海。'),
    ('广东省', '汕尾市'): ('汕尾市', '汕尾市，广东省辖地级市，位于广东省东南部沿海，处于莲花山南麓，珠江三角洲东岸，南濒南海，与台湾省一水之隔。'),
    ('广东省', '江门市'): ('江门市', '江门市，广东省辖地级市，别称五邑、四邑，地处广东省中南部、西江下游，珠江三角洲西岸。地势北低西高，以低山丘陵为主，东邻中山市、珠海市，西连阳江市，北接佛山市、云浮市，南临南海。'),
    ('广东省', '河源市'): ('河源市', '河源市，广东省辖地级市，别名槎城，位于广东省东北部、东江中上游，属南亚热带季风气候，气候温和，雨量充沛，处于粤东北山区与珠江三角洲平原地区的结合部，属山地丘陵地区，地势东北向西南倾斜，水系分为东江、北江、韩江三大流域，有近百条河流。'),
    ('广东省', '深圳市'): ('深圳市', '深圳市，简称“深”，别称鹏城，广东省辖地级市、副省级市、国家计划单列市，超大城市，深圳都市圈核心城市，位列世界一线城市。地处广东省南部，珠江口东岸，东临大亚湾和大鹏湾，西濒珠江口和伶仃洋，南与香港特别行政区相连，北部与东莞市、惠州市接壤，地形以丘陵为主，属亚热带季风气候，长夏短冬，雨量充沛。'),
    ('广东省', '清远市'): ('清远市', '清远市，广东省辖地级市，位于广东省的中北部、北江中下游、南岭山脉南侧与珠江三角洲的结合带上，南连广州市和佛山市，北接湖南省和广西壮族自治区，东及东北部和韶关市交界，西及西南部与肇庆市为邻，行政。'),
    ('广东省', '湛江市'): ('湛江市', '湛江市，中国广东省辖地级市，旧称“广州湾”，别称“港城”，位于中国大陆最南端、广东省西南部，介于东经109°40′～110°58′，北纬20°13′～21°57′之间。'),
    ('广东省', '潮州市'): ('潮州市', '潮州市，简称“潮”，别称凤城，广东省地级市，是潮汕四市之一，著名的华侨之乡，粤东门户城市。位于广东省最东部，下辖3个区县：湘桥、潮安和饶平。'),
    ('广东省', '珠海市'): ('珠海市', '珠海市，别称百岛之市、浪漫之城。是中华人民共和国广东省辖地级市，改革开放时期初步设立的四个经济特区之一，珠江口西岸都市圈城市之一。位于广东省南部，珠江口西岸。全国唯一以整体城市景观入选“中国旅游胜地四十佳”的城市。作为珠江三角洲城市群独树一帜的新型花园城市，是国家颁布的“幸福之城”，其146个海岛星罗棋布在漫长的海岸线上，为珠海赢得“百岛之市”的美誉。珠海市主要地貌有山地...。'),
    ('广东省', '肇庆市'): ('肇庆市', '肇庆市，广东省辖地级市，位于广东省中西部，东部和东南部分别与佛山市接壤，西南与云浮市相连，西部及西北部与广西壮族自治区的梧州市、贺州市交界，北部和东北部与清远市相邻。市内主要流行粤方言和客家方言。全市有3个市辖区、4个县，代管1个县级市。'),
    ('广东省', '茂名市'): ('茂名市', '茂名市，广东省辖地级市，别称南方油城。地处中国南海之滨，广东省西南部，背靠祖国大西南，背山面海，地势北高南低，由东北向西南倾斜，兼具全地形特征。'),
    ('广东省', '阳江市'): ('阳江市', '阳江市，广东省辖地级市，别称鼍城、阳江城。地处广东西南沿海，扼粤西要冲，东部、西部和北部为群山所环抱，南面濒临南海，属亚热带季风气候。'),
    ('广东省', '韶关市'): ('韶关市', '韶关市，古称韶州。广东省地级市，位于广东省北部，北界湖南，东邻江西，东南面、南面和西面分别与本省河源、惠州、广州及清远等市接壤。介于北纬23°53′～25°31′，东经112°53′～114°45′之间。'),
    ('广西壮族自治区', '北海市'): ('北海市', '北海市，广西壮族自治区辖地级市，别名“珠城”，地处广西壮族自治区南端，北部湾东北岸，地势总体呈北高南低，地形平坦开阔；气候属海洋性季风气候，具有典型的亚热带特色。'),
    ('广西壮族自治区', '南宁市'): ('南宁市', '南宁市简称“邕”，古称邕州，别称绿城，是广西壮族自治区首府及地级市，为Ⅰ型大城市。地处广西中部偏南，面向东南亚，背靠大西南，东接粤港澳，南临北部湾；市域地形以邕江广大河谷为中心，形成向东开口的盆地，南、北、西三面环山，属亚热带季风气候，降水丰沛。'),
    ('广西壮族自治区', '崇左市'): ('崇左市', '崇左市是广西壮族自治区辖地级市，是珠江—西江经济带、北部湾城市群和广西北部湾经济区的重要节点城市，位于广西壮族自治区西南部（北纬21°36`~23°22`，东经106°33`~108°6`之间），东和东南部接中国南宁市、防城港市，北邻百色市，西与越南接壤，是广西边境线陆路最长的地级市。'),
    ('广西壮族自治区', '来宾市'): ('来宾市', '来宾市，广西壮族自治区辖地级市，位于北纬23°16′10′′~24°28′14′′，东经108°24′39′′~110°27′18′′，居广西壮族自治区中部偏东北，故有“桂中”之称，地处亚热带，受季风环流影响，夏季盛行温暖湿润的海洋气团，冬季多寒冷干燥的大陆气团，故夏长冬短，雨热同季，行政区域。'),
    ('广西壮族自治区', '柳州市'): ('柳州市', '柳州市，简称“柳”，又称龙城，广西壮族自治区辖地级市，省域副中心城市，国务院批复确定的广西中部重要中心城市。位于广西壮族自治区北部，属亚热带季风气候。'),
    ('广西壮族自治区', '桂林市'): ('桂林市', '桂林市，简称“桂”，古称桂州、静江、始安，广西壮族自治区辖地级市，省域副中心城市，地处中国华南，湘桂走廊南端，位于南岭山系西南部、桂林—阳朔岩溶盆地北端中部，处在“湘桂夹道”中，属亚热带季风气候。'),
    ('广西壮族自治区', '梧州市'): ('梧州市', '梧州市，古称“苍梧”“广信”，，英文名为Wuzhou、Ngchow、Wuchow，是广西壮族自治区下辖地级市。梧州位于广西壮族自治区东部，扼浔江、桂江、西江总汇。'),
    ('广西壮族自治区', '河池市'): ('河池市', '河池市，简称“河”，广西壮族自治区辖地级市，地处广西北部、云贵高原南麓，境内地形多样，结构复杂，地势西北高东南低，属亚热带季风气候，热量丰富，光照充足，雨量充沛，全市东西宽228千米，南北长260千米。'),
    ('广西壮族自治区', '玉林市'): ('玉林市', '玉林市，隶属于中国广西壮族自治区，位于桂东南丘陵区，东邻粤港澳，南接北部湾，背靠大西南，面向东南亚。'),
    ('广西壮族自治区', '百色市'): ('百色市', '百色市，广西壮族自治区辖地级市，位于广西壮族自治区西部，右江上游，西与云南省文山州相接，北与贵州省黔西南州毗邻，东与广西壮族自治区首府南宁市紧连，南与越南接壤；地形为南北高中间低，地势走向由西北向东南倾斜，属亚热带季风气候。'),
    ('广西壮族自治区', '贵港市'): ('贵港市', '贵港市，又称荷城，广西壮族自治区辖地级市，位于广西东南部、珠江流域干线西江中游。处于东经109°11′~110°40′，北纬22°39′~24°02′之间。'),
    ('广西壮族自治区', '贺州市'): ('贺州市', '贺州市，广西壮族自治区辖地级市，地处湘、粤、桂三省（自治区）交界地，行政区域。'),
    ('广西壮族自治区', '钦州市'): ('钦州市', '钦州市，古称安州，广西壮族自治区辖地级市。地处广西壮族自治区南部沿海，北部湾北岸，主要属丘陵地貌类型，海洋性气候明显，东与北海市和玉林市相连，南临钦州湾，西与防城港市毗邻，北与南宁市接壤，全市。'),
    ('广西壮族自治区', '防城港市'): ('防城港市', '防城港市，又称渔城，港城，是广西壮族自治区辖地级市，位于广西壮族自治区南部、中国大陆海岸线最西南端，东与钦州市毗邻，南濒北部湾，西南与越南交界，西与宁明县接壤，北接南宁市的邕宁县和崇左市的扶绥县。'),
    ('新疆维吾尔自治区', '乌鲁木齐市'): ('乌鲁木齐市', '乌鲁木齐市，新疆维吾尔自治区下辖地级市、首府城市，通称乌市，旧称迪化，位于中国西北地区、新疆维吾尔自治区中部、亚欧大陆腹地，位于北天山北麓、准噶尔盆地南缘，深居内陆，属于中温带大陆干旱气候。'),
    ('新疆维吾尔自治区', '五家渠市'): ('五家渠市', '五家渠市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第六师实行师市合一管理体制，由新疆生产建设兵团管理。位于天山山脉博格达峰北麓，准噶尔盆地南缘，南北长75千米，东西宽29千米。'),
    ('新疆维吾尔自治区', '伊犁哈萨克自治州'): ('伊犁哈萨克自治州', '伊犁哈萨克自治州是新疆维吾尔自治区下辖的自治州，位于新疆西北部。'),
    ('新疆维吾尔自治区', '克孜勒苏柯尔克孜自治州'): ('克孜勒苏柯尔克孜自治州', '克孜勒苏柯尔克孜自治州，简称“克州”，隶属于新疆维吾尔自治区，位于新疆维吾尔自治区西南部，是中国最西端的地级行政区，地跨天山山脉西南部、帕米尔高原东部、昆仑山北坡和塔里木盆地西北缘，自治州北部和西部分别与吉尔吉斯斯坦和塔吉克斯坦两国接壤，东部与阿克苏地区相连，南部与喀什地区毗邻，全州东西长约500千米，南北宽约140千米。'),
    ('新疆维吾尔自治区', '克拉玛依市'): ('克拉玛依市', '克拉玛依市，新疆维吾尔自治区下辖地级市，别称黑油山，位于东经84°44’~86°1’，北纬44°7’~46°8’之间，地处新疆维吾尔自治区北部，准噶尔盆地西北边缘，加依尔山南麓之间。'),
    ('新疆维吾尔自治区', '北屯市'): ('北屯市', '北屯市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第十师实行师市合一管理体制，由新疆生产建设兵团管理。北屯市位于新疆维吾尔自治区北部，地处阿尔泰山中段西南麓、准噶尔盆地北部，系典型的温带大陆性气候。'),
    ('新疆维吾尔自治区', '博尔塔拉蒙古自治州'): ('博尔塔拉蒙古自治州', '博尔塔拉蒙古自治州，简称“博州”，隶属于新疆维吾尔自治区，“博尔塔拉”系蒙古语，意为“银色的草原”，位于新疆维吾尔自治区西北边缘，地处欧亚大陆腹地，西、北、南三面环山属北温带大陆性干旱气候。'),
    ('新疆维吾尔自治区', '双河市'): ('双河市', '双河市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第五师实行师市合一管理体制，由新疆生产建设兵团管理。双河市地处新疆维吾尔自治区西北部、准噶尔盆地西南缘，与哈萨克斯坦共和国接壤，位于新疆维吾尔自治区博尔塔拉蒙古自治州（简称博州）境内，地跨博州的精河县、温泉县、博乐市和阿拉山口市，与博州各市、县交错相连。'),
    ('新疆维吾尔自治区', '可克达拉市'): ('可克达拉市', '可克达拉市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第四师实行师市合一管理体制，由新疆生产建设兵团管理。地处天山北麓西段，位于伊犁河谷，东起天山那拉提，东南北三面环山，西与哈萨克斯坦接壤。'),
    ('新疆维吾尔自治区', '吐鲁番市'): ('吐鲁番市', '吐鲁番市（维吾尔语：تۇرپانشەھىرى），新疆维吾尔自治区辖地级市，地处新疆维吾尔自治区中部、天山东部，为东西横置的形如橄榄状的山间盆地，四面环山，属于典型的大陆性暖温带荒漠气候，热量丰富但又极端干燥，降雨稀少且大风频繁。'),
    ('新疆维吾尔自治区', '和田地区'): ('和田地区', '和田地区（维吾尔语：خوتەنۋىلايىتى），是新疆维吾尔自治区的5个地区之一，驻地和田市。南抵昆仑山与西藏自治区交界，北临塔克拉玛干大沙漠与阿克苏相连，东部与巴音郭楞蒙古自治州相接，西部与喀什地区毗邻，西南以喀喇昆仑山为界，同克什米尔接壤。'),
    ('新疆维吾尔自治区', '哈密市'): ('哈密市', '哈密市，古称昆莫、昆吾、伊州、伊吾、哈密卫，中国新疆维吾尔自治区下辖地级市，位于新疆东部，地跨东天山南北，东西相距约404千米，南北相距约440千米，东部、东南部与甘肃省酒泉市为邻，南接巴音郭楞蒙古自治州，西部、西南部与昌吉回族自治州、吐鲁番市毗邻，北部、东北部与蒙古国接壤。'),
    ('新疆维吾尔自治区', '喀什地区'): ('喀什地区', '喀什地区（维吾尔语：شىنجاڭقەشقەر），新疆维吾尔自治区辖地区；地处新疆维吾尔自治区西南部，整个地势由西南向东北倾斜，西、南、东三面环山，属暖温带大陆性干旱气候带，四季分明，降水很少，蒸发旺盛。'),
    ('新疆维吾尔自治区', '图木舒克市'): ('图木舒克市', '图木舒克市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第三师实行师市合一管理体制，由新疆生产建设兵团管理，位于新疆维吾尔自治区西南部，地处天山南麓、塔里木盆地西北缘，属暖温带大陆性干旱气候。'),
    ('新疆维吾尔自治区', '塔城地区'): ('塔城地区', '塔城地区，隶属于新疆维吾尔自治区，由伊犁哈萨克自治州管辖，位于新疆维吾尔自治区西北部，伊犁哈萨克自治州中部，横跨准噶尔盆地西北部及西部山区，边境线长540.6千米，约占新疆陆地国界线的十分之一。'),
    ('新疆维吾尔自治区', '巴音郭楞蒙古自治州'): ('巴音郭楞蒙古自治州', '巴音郭楞蒙古自治州，简称“巴州”，隶属于新疆维吾尔自治区，位于新疆维吾尔自治区东南部，境内有高山、盆地、河流、湖泊、戈壁、沙漠和平原绿洲，属中温带和暖温带大陆性气候。'),
    ('新疆维吾尔自治区', '新星市'): ('新星市', '新星市，别称红星、黄田，新疆维吾尔自治区直辖县级市，由新疆生产建设兵团管理，与新疆生产建设兵团第十三师实行师市合一管理体制，地处新疆东部哈密山南垦区。'),
    ('新疆维吾尔自治区', '昆玉市'): ('昆玉市', '昆玉市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第十四师实行师市合一管理体制，由新疆生产建设兵团管理。地处昆仑山北麓、塔里木盆地西南部，总计。'),
    ('新疆维吾尔自治区', '昌吉回族自治州'): ('昌吉回族自治州', '昌吉回族自治州，简称“昌吉州”，新疆维吾尔自治区辖自治州，是全国两个回族自治州之一，首府驻昌吉市，地处天山北麓，准噶尔盆地东南缘，地势南高北低，由东南向西北倾斜，属中温带区，为典型的大陆性干旱气候。'),
    ('新疆维吾尔自治区', '白杨市'): ('白杨市', '白杨市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第九师实行师市合一管理体制，由新疆生产建设兵团管理。白杨市地处新疆生产建设兵团第九师163团富兴镇，东距塔城市12公里，西临巴克图口岸；属北温带大陆性气候。'),
    ('新疆维吾尔自治区', '石河子市'): ('石河子市', '石河子市，中国新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第八师实行师市合一管理体制，由新疆生产建设兵团管理。地处天山北麓中段，准噶尔盆地南部。辖区。'),
    ('新疆维吾尔自治区', '胡杨河市'): ('胡杨河市', '胡杨河市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第七师实行师市合一管理体制，由新疆生产建设兵团管理。位于天山北麓中段，准噶尔盆地西南部，与克拉玛依市、奎屯市、乌苏市毗邻相接，这片区域统称为“三地四方”，被经济学界誉为新疆经济发展的“金三角”。'),
    ('新疆维吾尔自治区', '铁门关市'): ('铁门关市', '铁门关市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第二师实行师市合一管理体制，由新疆生产建设兵团管理。铁门关市地处天山南麓，塔里木盆地东部，位于于巴音郭楞蒙古自治州八县一市境内，北依天山，南依阿尔金山，天山支脉库鲁克山横贯垦区中部，形成“三山夹两盆”的格局，属北温带大陆极干旱气候。'),
    ('新疆维吾尔自治区', '阿克苏地区'): ('阿克苏地区', '阿克苏，新疆维吾尔自治区辖地区，地处中国西北地区，新疆中部，天山山脉中段南麓，塔里木盆地北部。东邻巴音郭楞蒙古自治州，西接克孜勒苏柯尔克孜自治州，西南与喀什地区接壤，南与和田地区相望，北与伊犁自治州毗邻，西北以天山山脉中梁与吉尔吉斯斯坦、哈萨克斯坦交界。'),
    ('新疆维吾尔自治区', '阿勒泰地区'): ('阿勒泰地区', '阿勒泰地区，新疆维吾尔自治区辖地区，由伊犁哈萨克自治州管理，地处新疆北部，位于阿尔泰山中段西南麓、准噶尔盆地北部，介于东经85°31′36″—91°04′23″，北纬45°00′00″—49°10′45″之间，与俄罗斯、哈萨克斯坦、蒙古三国接壤；地貌类型复杂多样，主要划分为山地、丘陵、平原和沙漠，夏季干热，冬季严寒；边境线长1197千米。'),
    ('新疆维吾尔自治区', '阿拉尔市'): ('阿拉尔市', '阿拉尔市，新疆维吾尔自治区直辖县级市，与新疆生产建设兵团第一师实行师市合一管理体制，由新疆生产建设兵团管理，地处新疆阿克苏地区旁，北起天山南麓山地，南至塔克拉玛干沙漠北缘，属暖温带极端大陆性干旱荒漠气候。'),
    ('江苏省', '南京市'): ('南京市', '南京市，简称“宁”，别称“金陵”“建康”，江苏省辖地级市，江苏省省会，是副省级市、特大城市、南京都市圈核心城市，是国务院批复确定的中国东部地区重要的中心城市、国际性综合交通枢纽城市，全国先进制造业基地、东部产业创新中心和区域性科技创新高地、东部现代服务业中心、区域性航运物流中心，也是中国人民解放军东部战区司令部驻地。南京市位于中国东部、江苏省西南部、长江下游，属北亚热带...。'),
    ('江苏省', '南通市'): ('南通市', '南通市，简称“通”，江苏省辖地级市，Ⅱ型大城市，地处江苏省东南部，中国东部海岸线与长江交汇处、长江入海口北翼，属长江三角洲冲积平原，处亚热带季风气候区。南通市南临长江，与苏州市、上海市跨江相连，东濒黄海，北接苏北平原。'),
    ('江苏省', '宿迁市'): ('宿迁市', '宿迁市，简称“宿”，古称下相、宿豫、钟吾等，中国江苏省下辖地级市，地处江苏省北部。'),
    ('江苏省', '常州市'): ('常州市', '常州市，江苏省辖地级市，地处江苏省南部、长江三角洲腹地，东与无锡市相邻，西与南京市、镇江市接壤，南与无锡市、安徽省宣城市交界，属长江下游平原，兼有高沙平原和山丘湖圩，地势西南略高、东北略低，为亚热带湿润季风气候，四季分明，雨量充沛。'),
    ('江苏省', '徐州市'): ('徐州市', '徐州市，简称“徐”，别名彭国、彭城、涿鹿、徐国，江苏省辖地级市，江苏省省域副中心城市，国务院批复确定的国家历史文化名城、全国性综合交通枢纽、淮海经济区中心城市。'),
    ('江苏省', '扬州市'): ('扬州市', '扬州市，古称“广陵”“江都”“维扬”，江苏省辖地级市，地处江苏省中部地区（苏中），位于长江北岸、江淮平原南端，是长江三角洲中心区城市，东部与盐城市、泰州市毗邻，南部濒临长江，与镇江市隔江相望，西南部与南京市相连，西部与安徽省滁州市交界，北部、西北部与淮安市接壤。'),
    ('江苏省', '无锡市'): ('无锡市', '无锡市，简称“锡”，江苏省辖地级市，Ⅰ型大城市，地处华东地区、江苏省南部，北依长江，南濒太湖，东邻苏州市，西连常州市，南和西南与浙江省湖州市、安徽省宣城市交界，京杭大运河穿境而过。'),
    ('江苏省', '泰州市'): ('泰州市', '泰州市，江苏省辖地级市，地处江苏省中部，介于北纬32°01′57″~33°10′59″，东经119°38′24″~120°32′20″之间，南濒长江、北邻盐城市、东临南通市、西接扬州市。'),
    ('江苏省', '淮安市'): ('淮安市', '淮安市，简称“淮”，旧称“清江”、“淮阴”，江苏省辖地级市，Ⅱ型大城市，地处江苏省中北部，江淮平原东部，地处长江三角洲地区，坐落于古淮河与京杭大运河交点，处在中国秦岭—淮河一线上。'),
    ('江苏省', '盐城市'): ('盐城市', '盐城市，古称“盐渎”，是江苏省辖地级市，位于东部沿海地区，江苏省东部，东临黄海；全境为平原地貌，地势西北部和东南部高，中部和东北部低洼，为北亚热带向暖温带气候过渡地带。'),
    ('江苏省', '苏州市'): ('苏州市', '苏州市，江苏省辖地级市，特大城市，位于中国华东地区，江苏省东南部，长江下游南岸，东傍上海市，南接浙江省嘉兴市、湖州市，西与无锡市相邻，是长江三角洲中心区城市。苏州市属长江三角洲平原和太湖平原地区，地势低平，境内河流纵横，湖泊众多，太湖水面绝大部分在苏州市境内。苏州市为亚热带季风海洋性气候。'),
    ('江苏省', '连云港市'): ('连云港市', '连云港市，古称“海州”，江苏省辖地级市，Ⅱ型大城市，位于中国沿海中部，东濒黄海，西连徐州市和宿迁市，南邻淮安市和盐城市，北接山东省日照市和临沂市。'),
    ('江苏省', '镇江市'): ('镇江市', '镇江市，中国江苏省下辖地级市，地处江苏省西南部，长江下游南岸。'),
    ('江西省', '上饶市'): ('上饶市', '上饶市，古称信州、广信，江西省辖地级市，位于江西省东北部，东邻浙江省，南邻福建省、江西省鹰潭市，西邻抚州市、南昌市、九江市，北与景德镇市、安徽省黄山市相依，地形以丘陵为主，南东高、北西低，西有鄱阳湖，属亚热带湿润型气候，总占地。'),
    ('江西省', '九江市'): ('九江市', "九江市，简称“浔”，古称“浔阳”、“柴桑”、“江州”，江西省辖地级市，地处江西省北部，赣、鄂、湘、皖四省交界处，介于东经113°56'~116°54'、北纬28°41'—30°05'之间，属亚热带季风气候，四季分明。"),
    ('江西省', '南昌市'): ('南昌市', '南昌市，简称洪或昌，是江西省辖地级市、省会、Ⅰ型大城市。位于江西省中部偏北，赣江、抚河下游，鄱阳湖西南岸，地形以平原为主，地势西北高、东南低，属亚热带季风气候，四季分明，雨量充沛。'),
    ('江西省', '吉安市'): ('吉安市', '吉安市，江西省辖地级市，古称庐陵、吉州，位于江西省中部，赣江中游，西接湖南省，南揽罗霄山脉中段，据富饶的吉泰平原，地形以山地、丘陵为主，属亚热带湿润性气候。'),
    ('江西省', '宜春市'): ('宜春市', '宜春市，古称袁州，位于江西省西北部，东与南昌市接界，东南与抚州市为邻，南陲与吉安市及新余市毗连，西南与萍乡市接壤，西北与湖南省长沙市及岳阳市交界，北与九江市相邻。'),
    ('江西省', '抚州市'): ('抚州市', '抚州市，江西省辖地级市，境内东、南、西三面环山，地势南高北低，属南方湿润多雨季风气候。'),
    ('江西省', '新余市'): ('新余市', '新余市，别称钢城，江西省辖地级市，长江中游城市群重要成员，位于江西省中部偏西，东临樟树市、新干县，西接宜春市袁州区，南连吉安县、安福县、峡江县，北毗上高县、高安市。地处北纬27°33′～28°05′，东经114°29′～115°24′之间，地貌基本形态有低山、高丘陵、低丘陵、岗地、阶地、平原6种类型；气候属亚热带湿润性气候，袁河是流经新余市的主要河流。'),
    ('江西省', '景德镇市'): ('景德镇市', '景德镇市，江西省辖地级市，位于江西省东北部，西北与安徽省东至县交界，南与万年县为邻，西同鄱阳县接壤，东北倚安徽省祁门县，东南和婺源县毗连。'),
    ('江西省', '萍乡市'): ('萍乡市', '萍乡市，江西省辖地级市，长江中游城市群重要成员，位于江西省西部，东与宜春市、吉安市接壤，南与吉安市和湖南省株洲市毗邻，西与湖南省株洲市相连，北与湖南省长沙市交界，地貌较为复杂，属亚热带湿润季风气候区，四季分明。'),
    ('江西省', '赣州市'): ('赣州市', '赣州市，简称“虔”，别称“虔城”、“赣南”，是江西省地级市，省域副中心城市、Ⅱ型大城市，三线城市，位于江西省南部，地处中亚热带南缘，属亚热带丘陵山区湿润季风气候，地形以山地、丘陵、盆地为主，章江、贡江在赣州合流为赣江。'),
    ('江西省', '鹰潭市'): ('鹰潭市', '鹰潭市，是中华人民共和国江西省下辖的地级市，位于江西省东北部。市境南、西界抚州市，北、东邻上饶市，东南与福建省南平市接壤。地处武夷山脉与鄱阳湖平原过渡带，地势东南高，西北低，北部属怀玉山余脉西段，南部属武夷山脉西北翼。信江自东往西横贯中部，于西部纳其支流白塔河，鹰潭是中国重要的铜工业基地和铁路枢纽，沪昆、鹰厦、皖赣等铁路在此交汇，市政府驻鹰潭市月湖区经济大厦。鹰潭市境内龙虎山是古典名著《水浒传》开篇所描绘的古今名山，以丹霞绝美、道宗绝圣、古越绝唱、阴阳绝妙享誉海内外，是世界自然遗产地、世界地质公园、国家5A级旅游景区；。'),
    ('河北省', '保定市'): ('保定市', '保定市，中国河北省辖地级市，地处河北省中部偏西，太行山东麓、冀中平原西部，地理坐标为北纬38°14′29″~39°57′3″、东经113°45′32″~116°19′41″。该市东接雄安新区，东南邻沧州，南连衡水，西南接石家庄，西、北与山西、张家口交界，北邻北京，东北与廊坊毗邻。境内地势西北向东南倾斜，地貌分山区、平原两类。'),
    ('河北省', '唐山市'): ('唐山市', '唐山市，简称唐，河北省辖地级市，地处河北东部、华北平原东北部，南临渤海，北依燕山，毗邻京津，地处华北与东北通道的咽喉要地。'),
    ('河北省', '廊坊市'): ('廊坊市', '廊坊市，是中国综合算力第一城、河北省辖地级市，地处河北省中部偏东，北临北京市，东与天津市交界，南接沧州市，西和保定市及雄安新区毗连，地处京津冀城市群核心地带、环渤海腹地；市域地貌以平原为主，属暖温带大陆性季风气候。'),
    ('河北省', '张家口市'): ('张家口市', '张家口市，河北省下辖地级市，Ⅱ型大城市，下辖6区10县。京冀晋蒙交界区域中心城市，国家可再生能源示范区、世界冰雪运动休闲胜地，首都水源涵养功能区和生态环境支撑区。地处河北省西北部，东靠河北省承德市，东南毗连北京市，南邻河北省保定市，西、西南与山西省接壤，北、西北与内蒙古自治区交界，地势西北高、东南低，属于温带大陆性季风气候。'),
    ('河北省', '承德市'): ('承德市', '承德市，别称“热河”，是河北省下辖地级市，京津冀城市群重要节点、京津冀水源涵养功能区、国家生态文明建设示范区、国家可持续发展议程创新示范区、国家历史文化名城，国际生态旅游城市。'),
    ('河北省', '沧州市'): ('沧州市', '沧州市，河北省辖地级市，地处河北东南部、河北平原东部的黑龙港流域，位于冀中平原东部，地势低平，起伏不大，自西南向东北倾斜，属暖温带大陆季风气候，四季分明，日照充足。市中心北距天津120千米、北京240千米，西南距省会石家庄220千米，是北京和天津的南大门。'),
    ('河北省', '石家庄市'): ('石家庄市', '石家庄市，简称“石”，河北省辖地级市、省会、Ⅰ型大城市、石家庄都市圈核心城市，地处中国华北地区、河北省中南部，地跨太行山和华北平原，属暖温带大陆性季风气候，四季分明，夏冬季长。'),
    ('河北省', '秦皇岛市'): ('秦皇岛市', '秦皇岛市，简称“秦”，别称港城，是河北省下辖地级市，为Ⅱ型大城市，地处中国华北地区、河北省东北部，南临渤海，北依燕山，东接辽宁，西近京津，地处华北、东北两大经济区结合部，居环渤海经济圈中心地带，是首都经济圈的重要功能区、首批沿海开放城市。秦皇岛市是国务院批复确定的京津冀地区重要的节点城市、现代海洋城市、全国性综合交通枢纽城市，是全国滨海旅游目的地。'),
    ('河北省', '衡水市'): ('衡水市', '衡水市，中国河北省下辖地级市，石家庄都市圈组成城市，位于河北省东南部，介于东经115°10′-116°34′，北纬37°03′-38°23′之间，东部与沧州市和山东省德州市毗邻，西部与石家庄市接壤，南部与邢台市相连，北部同保定市和沧州市交界。'),
    ('河北省', '邢台市'): ('邢台市', '邢台市，简称“邢”，古称邢州、顺德府，是河北省下辖地级市，Ⅱ型大城市，全国先进装备制造、新能源、健康食品产业重要基地和历史文化名城，京津冀联动中原的现代化重要节点城市、生态宜居太行泉城。石家庄都市圈重要节点城市。'),
    ('河北省', '邯郸市'): ('邯郸市', '邯郸市，河北省辖地级市，地处河北省南端，西依太行山脉，东接华北平原，与晋、鲁、豫三省接壤。'),
    ('河南省', '三门峡市'): ('三门峡市', '三门峡市，河南省辖地级市，别称陕州，地处河南省西部，位于黄河以南，豫晋陕三省交界处，大部分属于暖温带大陆性季风型半干旱气候，地貌以山地、丘陵和黄土塬为主。'),
    ('河南省', '信阳市'): ('信阳市', '信阳市，别名申城，是河南省辖地级市，位于河南省南部，鄂、豫、皖三省交界处，地势南高北低，西部和南部是由桐柏山、大别山构成的豫南山地，中部为丘陵岗地，北部为黄淮平原和洼地，属亚热带向暖温带过渡地区，季风气候明显。'),
    ('河南省', '南阳市'): ('南阳市', '南阳市，古称宛，河南省辖地级市、省域副中心城市，国务院批复确定的中部地区重要的交通枢纽，豫鄂陕交界地区区域性中心城市。地处北纬32°17′~33°48′，东经110°58′~113°49′。'),
    ('河南省', '周口市'): ('周口市', '周口市，河南省辖地级市，位于河南省东南部，地处黄淮平原腹地，东邻安徽阜阳市、亳州市，西接河南漯河市、许昌市，南与河南驻马店市相连，北和河南开封市、商丘市接壤，地势西北高，东南低。'),
    ('河南省', '商丘市'): ('商丘市', '商丘市，河南省辖地级市，位于河南省东部，简称“商”，地处豫鲁苏皖四省接合部，主要为黄河冲积平原区，属暖温带半湿润大陆性季风气候，市域。'),
    ('河南省', '安阳市'): ('安阳市', '安阳市，河南省辖地级市，古称相州、彰德等，简称殷、邺，位于河南省最北部，豫、晋、冀三省交界处，西邻长治市，东接濮阳市，北邻邯郸市，南接鹤壁市、新乡市，位于北纬35°12′～36°22′、东经113°37′～114°58′之间。'),
    ('河南省', '平顶山市'): ('平顶山市', '平顶山市，古为应国，古应国以鹰为图腾，“应”“鹰”通假，故有“鹰城”之称，河南省辖地级市，地势西高东低，呈梯形展布，西依八百里伏牛山，东临黄淮平原，处于暖温带和北亚热带气候交错的边缘地区，冬冷夏热，年温差大，降水量小，四季分明。'),
    ('河南省', '开封市'): ('开封市', '开封市，简称“汴”，古称老丘、大梁、汴州、陈留、汴梁、汴京、东都、东京，河南省辖地级市，河南省原省会。位于河南省东部，黄河中下游。中原腹地、黄河之滨，紧临河南省会郑州。'),
    ('河南省', '新乡市'): ('新乡市', '新乡市，古称牧野，河南省辖地级市，三线城市。位于河南省北部，南临黄河，与河南郑州市、开封市隔河相望；北依太行山，与河南鹤壁市、安阳市毗邻；西连河南焦作市，与山西接壤；东接河南濮阳市与山东相连。'),
    ('河南省', '洛阳市'): ('洛阳市', '洛阳市，河南省辖地级市，位于河南省西部。东邻郑州，西接三门峡，南与平顶山、南阳相连，北与焦作、济源接壤。'),
    ('河南省', '济源市'): ('济源市', '济源市，河南省直辖县级市，位于河南省西北部；地形北高南低，地貌复杂，山势陡峭，属暖温带季风气候。'),
    ('河南省', '漯河市'): ('漯河市', '漯河市，河南省辖地级市，别名河上街、隐阳城，位于河南省中南部，伏牛山东麓平原与淮北平原交错地带，处于暖温带的南部边缘地区，属于温暖过渡型季风气候。'),
    ('河南省', '濮阳市'): ('濮阳市', '濮阳市，古称帝丘、澶州、开州等，河南省辖地级市，四线城市，位于河南省东北部，是豫鲁冀省际交会区域性中心城市，东、南部与山东省济宁市、菏泽市相望，西部与河南省安阳市接壤，北部与河北省邯郸市相连，东北部和山东省聊城市、泰安市毗邻，西南部与河南省新乡市相依。'),
    ('河南省', '焦作市'): ('焦作市', '焦作市，河南省辖地级市，位于河南省西北部，北与山西省晋城市陵川县、泽州县搭界，南与郑州市荥阳市、巩义市、惠济区，洛阳市孟津区、偃师区隔河相望，西与济源市毗邻，东与新乡市辉县市、获嘉县、原阳县接壤，属暖温带大陆性季风气候，四季分明。'),
    ('河南省', '许昌市'): ('许昌市', '许昌市，河南省辖地级市，古称许州，别称莲城、许都、魏都、汉魏故都，位于河南省中部，东邻周口市，南界漯河市，西交平顶山市，北接郑州市，东北与开封市毗邻，地势西北高，东南低，雨量充沛，阳光充足。'),
    ('河南省', '郑州市'): ('郑州市', '郑州市，简称“郑”，河南省辖地级市、省会，特大城市、新一线城市，史谓“天地之中”，别称商都、绿城，地处河南省中北部，黄河中、下游分界处，总的地势为西南高、东北低，呈阶梯状下降，由西部、西南部构造侵蚀中低山，逐渐下降过渡为构造剥蚀丘陵、黄土丘陵、倾斜平原和冲积平原。属温带大陆性季风气候，四季分明，气候温和，雨热同季，境内有大小河流124条，地跨黄河、淮河两大流域。全市...。'),
    ('河南省', '驻马店市'): ('驻马店市', '驻马店市，河南省辖地级市，别称汝宁、蔡州、天中，位于河南省中南部，东与安徽阜阳市接壤，西与河南南阳市相连，北与河南周口、平顶山和漯河为界，南与河南信阳市毗邻，属于大陆性季风型半湿润气候，阳光充足，主要有山地、丘陵、岗地、平原等地貌类型，东西横跨淮河、长江两大流域。'),
    ('河南省', '鹤壁市'): ('鹤壁市', '鹤壁市，古称朝歌，河南省辖地级市，位于河南省北部，太行山东麓向华北平原过渡地带。'),
    ('浙江省', '丽水市'): ('丽水市', '丽水市，古称处州，浙江省辖地级市，位于浙江省西南部；东南与温州市接壤，西南与福建省宁德市、南平市毗邻，西北与衢州市相接，北部与金华市交界，东北与台州市相连；地貌以中山、丘陵为主，由西南向东北倾斜，90%的辖区。'),
    ('浙江省', '台州市'): ('台州市', '台州市，浙江省辖地级市，位于浙江省沿海中部，东濒东海，南邻温州市，西连丽水市、金华市，北接绍兴市、宁波市；台州市居山面海，平原丘陵相间，形成“七山一水二分田”的格局，地势由西向东倾斜。'),
    ('浙江省', '嘉兴市'): ('嘉兴市', '嘉兴市，浙江省辖地级市，位于浙江省东北部、杭嘉湖平原腹地，东接上海市，北临江苏省苏州市，西邻杭州市、湖州市，与宁波市、绍兴市隔江相望；东临大海，南濒杭州湾钱塘江，京杭大运河夹城而过，扼太湖南走廊之咽喉，处江河湖海交会之位。嘉兴市是长三角核心区重要的中心城市，国家历史文化名城，长三角重要的科创和先进制造业城市。'),
    ('浙江省', '宁波市'): ('宁波市', '宁波市，简称“甬”，浙江省辖地级市，是副省级市、计划单列市，古称“句章”“四明”“明州”，地处浙江省东北部沿海，东有舟山群岛为天然屏障，北濒杭州湾，西接绍兴市的嵊州市、新昌县、上虞区，南临三门湾，并与台州市的三门县、天台县相连。地势西南高，东北低，地形以平原和低山丘陵为主，属亚热带季风气候。'),
    ('浙江省', '杭州市'): ('杭州市', '杭州市，简称“杭”，浙江省辖地级市，浙江省省会，是副省级市、超大城市、杭州都市圈核心城市，位于浙江省北部、钱塘江下游、京杭大运河南端，地势自西向东逐渐降低，丘陵、山地、平原等地形兼有，属亚热带季风气候，四季分明，雨量充沛。'),
    ('浙江省', '温州市'): ('温州市', '温州市，浙江省辖地级市，地处浙江省东南部，东濒东海，南毗福建省宁德市，西及西北部与丽水市相连，北和东北部与台州市接壤，地势从西南向东北呈现梯形倾斜，地形以山地丘陵为主，海岸曲折，良港众多，为中亚热带季风气候区，湿润多雨。'),
    ('浙江省', '湖州市'): ('湖州市', '湖州市，浙江省辖地级市，古称“吴兴”“菰城”，地处浙江省北部，浙苏皖三省交汇处，东邻嘉兴市、江苏省苏州市，南接杭州市，西邻安徽省宣城市，北与江苏省无锡市接壤，东北濒太湖，与江苏省无锡市隔湖相望。地势大致由西南向东北倾斜，西部多山，东部为平原水网区，有东苕溪、西苕溪等众多河流，属亚热带湿润季风气候，四季分明，雨量充沛。'),
    ('浙江省', '绍兴市'): ('绍兴市', '绍兴市，浙江省辖地级市，古称“会稽”“山阴”“越州”，位于浙江省中北部，杭州湾南岸，属亚热带季风气候，温暖湿润，四季分明。全境处于浙西山地丘陵、浙东丘陵山地和浙北平原三大地貌单元的交接地带，地势南高北低，形成群山环绕、盆地内含、平原集中的地貌特征，地形骨架呈“山”字形。地貌可概括为“四山三盆二江一平原”。'),
    ('浙江省', '舟山市'): ('舟山市', '舟山市，浙江省辖地级市，位于浙江省东北部舟山群岛，地处中国东南沿海，长江口南侧，杭州湾外缘的东海洋面上。地势由西南向东北倾斜，南部岛大，海拔高，排列密集，北部岛小，地势低，分布稀疏，四面环海；属亚热带季风气候。'),
    ('浙江省', '衢州市'): ('衢州市', '衢州市，浙江省辖地级市，位于浙江省西部，钱塘江上游，浙、皖、赣、闽四省交界处，南接福建省南平市，西连江西省上饶市，北邻安徽省黄山市，东与省内金华市、丽水市、杭州市三市相交；地处金衢盆地西段，以山地丘陵为主；属亚热带季风气候，四季分明，降水丰沛。'),
    ('浙江省', '金华市'): ('金华市', '金华市，浙江省辖地级市，位于浙江省中部，东邻台州市，南毗丽水市，西连衢州市，北接绍兴市、杭州市，属浙中丘陵盆地地区，地势南北高、中部低；为中亚热带季风气候，四季分明，年温适中，热量丰富，雨量较多。'),
    ('海南省', '万宁市'): ('万宁市', '万宁市，海南省直辖县级市，位于海南岛东南部沿海，地处东经110°00′—110°34′，北纬18°35′—19°06′之间。东临南海，南与陵水县毗邻，西与琼中县接壤，北与琼海市交界。'),
    ('海南省', '三亚市'): ('三亚市', '三亚市，简称崖，别称鹿城，古称崖州、崖县，是海南省辖地级市，地处海南岛的最南端，东邻陵水黎族自治县，西接乐东黎族自治县，北毗保亭黎族苗族自治县，南临南海。'),
    ('海南省', '三沙市'): ('三沙市', '三沙市，海南省辖地级市，地处中国南海中南部，海南省南部，辖西沙群岛、中沙群岛、南沙群岛的岛礁及其海域。'),
    ('海南省', '东方市'): ('东方市', '东方市，海南省辖县级市，位于海南岛西部，昌化江下游，地理坐标介于北纬18°43′08″—19°18′43″，东经108°36′46″—109°07′17″之间。'),
    ('海南省', '临高县'): ('临高县', '临高县，海南省直辖县，位于海南岛西北部，是北部湾城市群的重要组成部分，介于北纬19°34′—20°02′，东经109°3′—109°53′之间，全县。'),
    ('海南省', '乐东黎族自治县'): ('乐东黎族自治县', '乐东黎族自治县，是海南省直辖自治县，地处海南岛西南部，介于北纬18°24′至18°58′，东经108°39′至109°24′之间。地势北高南低，背山面海。东和东北与五指山市、白沙黎族自治县接壤，东南与三亚市交界，北与东方市、昌江黎族自治县毗邻，西南临南海。'),
    ('海南省', '五指山市'): ('五指山市', "五指山市，隶属海南省，为海南省直辖县级市，位于海南岛中南部五指山腹地，介于北纬18°38'—19°02'，东经109°19'—109°44'之间。"),
    ('海南省', '保亭黎族苗族自治县'): ('保亭黎族苗族自治县', '保亭黎族苗族自治县，海南省直辖自治县，地处海南岛中南部，介于北纬18°23′—18°53′，东经109°21′—109°48′之间，东接陵水黎族自治县，南邻三亚市，西连三亚市、乐东黎族自治县，北依五指山市、琼中黎族苗族自治县。'),
    ('海南省', '儋州市'): ('儋州市', '儋州市古称“儋耳”，海南省辖地级市，地处海南岛西北部，全市。'),
    ('海南省', '定安县'): ('定安县', '定安县，海南省直辖县，位于海南岛的中部偏东北，是“海口都市圈”卫星城，介于东经110°7′—110°31′，北纬19°13′—19°44′之间。'),
    ('海南省', '屯昌县'): ('屯昌县', '屯昌县，海南省直辖县，地处海南岛中部偏北，介于东经109°45′—110°15′，北纬19°8′—19°37′之间。'),
    ('海南省', '文昌市'): ('文昌市', '文昌市，海南省直辖县级市，位于海南省东北部，东、南、北三面临海，北枕琼州海峡。'),
    ('海南省', '昌江黎族自治县'): ('昌江黎族自治县', '昌江黎族自治县，海南省直辖自治县，位于环北部湾城市群内，地处海南岛西部，东与白沙黎族自治县毗邻，南与乐东黎族自治县接壤，西南与东方市对峙相望，西北濒临北部湾，东北部同儋州市相连，属典型的热带季风气候，土地肥沃，光照水分充足。'),
    ('海南省', '海口市'): ('海口市', '海口市，中国海南省下辖地级市、省会，地处海南岛北部，东邻文昌，西接澄迈，南毗定安，北濒琼州海峡，地形略呈长心形，地势平缓，位于低纬度热带北缘，属于热带季风气候。'),
    ('海南省', '澄迈县'): ('澄迈县', '澄迈县，海南省直辖县，位于海南岛西北部，是环北部湾城市群的重要组成部分，介于北纬19°23′—20°01′，东经109°45′—110°15′之间，全县。'),
    ('海南省', '琼中黎族苗族自治县'): ('琼中黎族苗族自治县', '琼中黎族苗族自治县，海南省辖自治县，位于海南岛中部，地理坐标介于北纬18°43′45″—19°25′20″，东经109°31′37″—110°09′08″之间。'),
    ('海南省', '琼海市'): ('琼海市', '琼海市，海南省直辖县级市，位于海南省东部，东临南海，北与文昌市、定安县交界，西与屯昌县、琼中黎族苗族自治县接壤，南与万宁市毗邻。'),
    ('海南省', '白沙黎族自治县'): ('白沙黎族自治县', '白沙黎族自治县，海南省直辖自治县，地处海南岛中部偏西，东邻琼中黎族苗族自治县、南接乐东黎族自治县、西连昌江黎族自治县、北抵儋州市，属热带季风性气候，日照长，光热充足。'),
    ('海南省', '陵水黎族自治县'): ('陵水黎族自治县', '陵水黎族自治县，海南省直辖自治县，位于海南岛东南部。'),
    ('湖北省', '仙桃市'): ('仙桃市', '仙桃市，旧称沔阳，湖北省直辖县级市，武汉都市圈、长江中游城市群成员，位于湖北中部，江汉平原腹地，北依汉水，南靠长江，东邻省会武汉，西连荆州、宜昌，处在湖北“两江”（长江、汉江）经济带的交汇点上。'),
    ('湖北省', '十堰市'): ('十堰市', '十堰市，别称车城、中国卡车之都，湖北省辖地级市，Ⅱ型大城市。介于北纬31°30′～33°16′，东经109°29′～111°16′，地处中国华中地区、湖北省西北部，汉江中上游地区，秦巴山区汉水谷地，北抵秦岭，南依巴山和汉江，武当山横贯全境。'),
    ('湖北省', '咸宁市'): ('咸宁市', '咸宁市，宋真宗景德四年（公元1007年），取《易经》“万国咸宁”之意得名，别称桂花城，湖北省辖地级市，地处中国华中地区、湖北省东南部，长江中游南岸，与湖南、江西接壤，气候温和，降水充沛，日照充足，四季分明，无霜期长；地势南高北低。'),
    ('湖北省', '天门市'): ('天门市', '天门市，古称竟陵，湖北省直辖县级市，地处湖北中南部、江汉平原北部，北抵大洪山，南濒汉江，东距武汉城区90千米，境内河流纵横、湖泊密布，属亚热带大陆性季风湿润气候地区，雨量充沛、物产丰富。'),
    ('湖北省', '孝感市'): ('孝感市', '孝感市，别称孝城、澴川，湖北省辖地级市，地处湖北省东北中部，桐柏山、大别山之南；长江以北，汉江以东；南与武汉市东西湖区及仙桃市毗邻，北与河南省信阳市浉河区、罗山县交界，西接随州市、荆门市、天门，东连黄冈市红安县与武汉市黄陂区，地貌自南向北为平原、丘陵、山区，气候为亚热带大陆性季风气候。'),
    ('湖北省', '宜昌市'): ('宜昌市', '宜昌市是湖北省辖地级市，地处湖北西南部、长江上游和中游的分界处，属亚热带季风性湿润气候，四季分明，水热同季，寒旱同季。'),
    ('湖北省', '恩施土家族苗族自治州'): ('恩施土家族苗族自治州', '恩施土家族苗族自治州，湖北省辖自治州，位于湖北省西南部，东连荆楚，南接潇湘，西临渝黔，北靠神农架，全州。'),
    ('湖北省', '武汉市'): ('武汉市', '武汉市，简称“汉”，别称“江城”，湖北省辖地级市、省会，中部六省唯一的副省级市、超大城市，国务院批复确定的中国中部地区的中心城市，国家历史文化名城，国际性综合交通枢纽城市，中部经济中心、科技创新中心、商贸物流中心、对外交往中心以及长江中游航运中心，也是中国人民解放军联勤保障部队机关驻地，全面创新改革试验区。'),
    ('湖北省', '潜江市'): ('潜江市', '潜江市，中国湖北省直辖县级市，地处湖北省中南部、江汉平原腹地，全市辖7个街道、10个镇。'),
    ('湖北省', '神农架林区'): ('神农架林区', '神农架林区，直属湖北省管辖，是中国唯一以林区命名的行政区，为副厅级建制。地处湖北省西北部，西与重庆市巫山县、巫溪县相邻，北接竹山县、房县，东连保康县，南濒兴山县、巴东县。'),
    ('湖北省', '荆州市'): ('荆州市', '荆州市，古称江陵、郢都、南郡，湖北省辖地级市，位于湖北省中南部、长江中游、江汉平原腹地。东依武汉市汉南区；南滨江与湖南省岳阳市为邻，与益阳市、常德市接壤；西连宜昌市的当阳市、枝江市、宜都市、五峰县，北接荆门市、潜江市、仙桃市。'),
    ('湖北省', '荆门市'): ('荆门市', '荆门市，别名“荆楚门户”，位于湖北省中部，为湖北省下辖地级市，位于东经111°51′—113°29′，北纬30°32′—31°36′，全市国土。'),
    ('湖北省', '襄阳市'): ('襄阳市', '襄阳市，曾用名襄樊，湖北省辖地级市，地处中国华中地区、湖北西北部，汉江中游，东邻随州市，南界荆门市、宜昌市，西连神农架林区、十堰市，北接河南省南阳市。'),
    ('湖北省', '鄂州市'): ('鄂州市', '鄂州市，旧称吴都、古武昌，湖北省辖地级市，位于湖北省东部，西与武汉市接壤，东南与黄石市毗连，北临长江，自西向东分别与武汉市、黄冈市隔江相望，辖区地域。'),
    ('湖北省', '随州市'): ('随州市', '随州市，中国湖北省辖地级市，位于湖北省北部，地理位置介于北纬31°19′至32°26′，东经112°43′至113°46′，东承武汉市，西接襄阳市，北临河南省南阳市、河南省信阳市，南接荆门市、孝感市。'),
    ('湖北省', '黄冈市'): ('黄冈市', '黄冈市，古称黄州，湖北省辖地级市，介于东经114°24′—116°07′、北纬29°45′—31°40′，地处鄂东、大别山南麓、长江中游北岸，京九铁路中段，与武汉市山水相连，北接河南省，东连安徽省，南与鄂州市、黄石市、九江市隔江相望；地势自北向南逐渐倾斜，东北部与豫皖交界为大别山脉。'),
    ('湖北省', '黄石市'): ('黄石市', '黄石市，湖北省辖地级市，位于湖北省东南部，长江中游南岸。'),
    ('湖南省', '娄底市'): ('娄底市', '娄底市，湖南省辖地级市，别称星城，地处湖南省的地理几何中心，位于北纬27°12′31″～28°14′27″、东经110°45′40″～112°31′7″之间。'),
    ('湖南省', '岳阳市'): ('岳阳市', '岳阳市，古称“巴陵”，又名“岳州”，湖南省辖地级市，位于湖南省东北部，北枕长江，南纳三湘四水，怀抱洞庭，江湖交汇，境内地貌类型多样，地势东高西低，呈阶梯状向洞庭湖盆地倾斜，属湿润的大陆性季风气候。'),
    ('湖南省', '常德市'): ('常德市', '常德市，古称武陵、朗州，湖南省辖地级市，位于湖南省西北部、江南洞庭湖西侧、武陵山下，区内基本地貌南北高，中间低，两山夹一凹，属于亚热带湿润季风气候，气候温暖，四季分明，春秋短，夏冬长。'),
    ('湖南省', '张家界市'): ('张家界市', '张家界市，原名“大庸”，是湖南省辖地级市，位于湖南省西北部，澧水中上游，属武陵山区腹地，光热充足，雨量充沛。'),
    ('湖南省', '怀化市'): ('怀化市', '怀化市，别称“鹤城”，古称“鹤州”“五溪”，湖南省辖地级市，位于湖南省西部偏南，处于武陵山脉和雪峰山脉之间，地处中亚热带川鄂湘黔气候区和江南气候区的过渡部位，境内四季分明，严寒酷暑期短。'),
    ('湖南省', '株洲市'): ('株洲市', '株洲市，古称建宁，湖南省辖地级市，长株潭都市圈成员城市。位于湖南省东部、湘江下游，东界江西省萍乡市、莲花县、永新县及井冈山市，南连衡阳市、郴州市二市，西接湘潭市，北与长沙市毗邻，地势东南高、西北低，气候温和，四季分明。'),
    ('湖南省', '永州市'): ('永州市', '永州市，别称“潇湘”，中国湖南省辖地级市，位于湖南南部、湘江上游，北邻衡阳、邵阳，东连郴州，西接广西桂林、贺州，南接广东清远。位于潇、湘二水汇合处，地势三面环山，西南高，东北及中部低；地貌类型复杂，以丘岗山地为主；属中亚热带湿润季风气候。'),
    ('湖南省', '湘潭市'): ('湘潭市', '湘潭市，湖南省辖地级市，简称潭，因盛产湘莲而别称“莲城”，又称“潭城”，总的地貌轮廓是北、西、南地势高，中部、东部地势低平。'),
    ('湖南省', '湘西土家族苗族自治州'): ('湘西土家族苗族自治州', '湘西土家族苗族自治州，湖南省辖自治州，地处湖南省西北部，位于湘鄂渝黔四省市交界处，北接湖北省，西与重庆市为邻，西南与贵州省接壤。行政区域。'),
    ('湖南省', '益阳市'): ('益阳市', '益阳市，别称银城、丽都，湖南省辖地级市，位于湖南省中北部，洞庭湖南岸，居雪峰山北段及其余脉带，北近长江，同湖北省石首市抵界，西和西南与常德市、怀化市接壤，南与娄底市毗邻，东和东南紧靠岳阳市、长沙市。'),
    ('湖南省', '衡阳市'): ('衡阳市', '衡阳市，别称雁城、衡州，湖南省辖地级市，位于中国南部，湖南省中南部，属于典型的盆地形势，南高北低，冬暖且春温高，入春后降水较集中，夏秋季节雨水充沛。'),
    ('湖南省', '邵阳市'): ('邵阳市', '邵阳市[shàoyángshì]，古称宝庆[bǎoqìng]，湖南省辖地级市，位于湘中偏西南，资江上游；中间为丘陵盆地，东与衡阳为邻，南与永州和桂林接壤，西与怀化交界，北与娄底毗连。'),
    ('湖南省', '郴州市'): ('郴州市', '郴州市别称“福城”“林城”，位于中国湖南省东南部，是湖南省下辖地级市。'),
    ('湖南省', '长沙市'): ('长沙市', '长沙市，别称“星城”，湖南省辖地级市，省会，特大城市，长株潭都市圈核心城市，位于湖南省东部偏北，湘江下游和长浏盆地西缘，市境地形复杂，湘江两岸形成地势低平的冲积平原，东西两侧及东南面为地势较高的低山、丘陵，属亚热带季风气候，具有春温变化大，夏初雨水多，伏秋高温久，冬季严寒少的特点。'),
    ('澳门特别行政区', '澳门特别行政区'): ('澳门特别行政区', '澳门特别行政区，简称“澳”，是直辖于中华人民共和国中央人民政府的特别行政区。位于中国南部珠江口西侧，是中国内地与南海的水陆交汇处，毗邻广东省，与香港特别行政区相距60千米，距离广东省广州市145千米。澳门特别行政区由澳门半岛和氹仔、路环二岛以及路氹城（路氹填海区）组成，下辖7个堂区。'),
    ('甘肃省', '临夏回族自治州'): ('临夏回族自治州', '临夏回族自治州，简称“临夏州”，古称河州，是甘肃省辖自治州，全国两个回族自治州和甘肃两个民族自治州之一，地处中国西部地区，甘肃省中部西南面，黄河上游，西南部山区高寒阴湿，东北部干旱，河谷川塬区温和。'),
    ('甘肃省', '兰州市'): ('兰州市', '兰州市，简称“兰”“皋”，别称金城，是中国甘肃省下辖地级市、省会，位于中国西北部、甘肃省中部，是中国陆域版图的几何中心，北与武威市、白银市接壤，东与定西市接壤、南与临夏回族自治州接壤。兰州市属温带半干旱气候，夏无酷暑，冬无严寒，年平均气温10.9℃，具有山地、丘陵、山间盆地、河谷四种地貌单元，地势总体上南高北低，属黄河流域。'),
    ('甘肃省', '嘉峪关市'): ('嘉峪关市', '嘉峪关市，甘肃省辖地级市，地处甘肃省西北部，河西走廊的中部，境内地势平坦，属温带大陆性荒漠气候。'),
    ('甘肃省', '天水市'): ('天水市', '天水市，古称邽、别名秦州，甘肃省辖地级市，陇东南区域中心城市、关中平原城市群重要节点城市。位于甘肃省东南部，自古为陇右要冲、关中屏障。地处长江、黄河两大流域，属暖温带半湿润气候，是西北最大的天然林基地。'),
    ('甘肃省', '定西市'): ('定西市', '定西市，通称“陇中”，是中国甘肃省下辖地级市，地处内陆腹地，地形复杂，气候差异大，中北部干旱少雨，南部高寒阴湿其气候类型属南温带半湿润-中温带半干旱区，大陆性季风气候明显，地貌比较复杂，丘陵起伏，沟壑纵横，海拔1420—3941米，年降水量350—600毫米，年平均气温7℃。'),
    ('甘肃省', '平凉市'): ('平凉市', '平凉市，甘肃省地级市，地处甘肃省东部，陕甘宁三省（区）交汇处，东邻陕西咸阳，西连甘肃定西、白银，南接陕西宝鸡、甘肃天水，北倚宁夏固原、甘肃庆阳。'),
    ('甘肃省', '庆阳市'): ('庆阳市', '庆阳市，甘肃省辖地级市，位于甘肃省东部，东接陕西省的宜君、黄陵、富县、甘泉、志丹等县；北邻陕西省定边、吴起、志丹县及宁夏盐池县；西与宁夏固原市原州区、彭阳县、同心县接壤；南与本省的泾川县及陕西的彬州市、长武、旬邑县相连。'),
    ('甘肃省', '张掖市'): ('张掖市', "张掖市，古称甘州，是中国甘肃省辖地级市，位于甘肃省西北部，河西走廊中段，介于北纬37°51'24″—39°53'19″、东经97°23'38″—102°37'57″之间，东与金昌市、武威市为邻，南与青海省海北藏族自治州门源回族自治县和祁连县接壤，西与酒泉市、嘉峪关市毗邻，北与内蒙古自治区阿拉善盟额济纳旗和阿拉善右旗交界，属温带大陆性干旱气候。"),
    ('甘肃省', '武威市'): ('武威市', '武威市，甘肃省辖地级市，简称“武”或“凉”，古称凉州、姑臧、雍州，地处中国西北地区，甘肃省中部，东接兰州市、南靠西宁市、北临银川市和内蒙古、西接金昌市和张掖市，地势西高东低，局部地形复杂，属温带大陆性干旱气候。'),
    ('甘肃省', '甘南藏族自治州'): ('甘南藏族自治州', '甘南藏族自治州，简称“甘南州”，甘肃省辖自治州。位于甘肃省西南部，地处青藏高原东北边缘与黄土高原西部过渡地段，是藏、汉文化的交汇带，是黄河、长江的水源涵养区和补给区。东与定西市、陇南市毗邻，南与四川阿坝藏族羌族自治州相连，西与青海省果洛藏族自治州、黄南藏族自治州相连，北靠临夏回族自治州。'),
    ('甘肃省', '白银市'): ('白银市', '白银市，别称铜城，甘肃省辖地级市，地处中国西北地区、黄河上游、甘肃省中部、陕甘宁青四省区交汇处，地势南北高，中部低，以基岩山地和山间盆地为主，属东南季风气候西北部边缘区。'),
    ('甘肃省', '酒泉市'): ('酒泉市', '酒泉市，古称“肃州”，甘肃省辖地级市、地处甘肃省西北部，位于东经92°23′~100°21′、北纬38°05′~42°43′之间。'),
    ('甘肃省', '金昌市'): ('金昌市', '金昌市，别称镍都，是中国甘肃省下辖地级市。金昌市地处中国西北地区、甘肃省河西走廊中段、祁连山北麓，地势南高北低，属大陆性温带干旱气候。'),
    ('甘肃省', '陇南市'): ('陇南市', '陇南市，中国甘肃省辖地级市，位于甘肃东南部，东接秦巴山地，南抵四川盆地，西依甘南高原与迭部县、舟曲县和定西岷县，北与天水市接壤。'),
    ('福建省', '三明市'): ('三明市', '三明市，别称“绿都”，福建省下辖地级市，地处福建省中北部，介于北纬25°30′～27°07′，东经116°22′～118°39′。东依福州市、南靠泉州市、西南接龙岩市、西濒江西省、北通南平市。'),
    ('福建省', '南平市'): ('南平市', '南平市，福建省辖地级市，Ⅰ型小城市，介于东经117°00′—119°25′，北纬26°30′—28°20′之间，地处福建省北部，武夷山脉北段东南侧，位于闽、浙、赣三省交界处，俗称“闽北”，东北与浙江衢州、丽水相邻，西北与江西抚州、上饶接壤，东南与福州、宁德交界，西南与三明毗邻。'),
    ('福建省', '厦门市'): ('厦门市', '厦门市，简称“厦”或“鹭”，福建省辖地级市、副省级市、计划单列市、厦漳泉都市圈城市、Ⅰ型大城市，位于福建省东南部沿海，境域由福建省东南部沿厦门湾的大陆地区和厦门岛、鼓浪屿等岛屿以及厦门湾组成，地形以滨海平原、台地和丘陵为主，属南亚热带海洋性季风气候，温和多雨，冬无严寒，夏无酷暑。'),
    ('福建省', '宁德市'): ('宁德市', '宁德市，俗称闽东，福建省辖地级市，位于福建省东北翼沿海、福建闽东地区，地处东亚大陆边缘濒太平洋新华夏系构造带中，地貌以山地、丘陵为主，地势西、北部高，东、南部低，大致呈”门”型的梯状地势，属亚热带季风气候。'),
    ('福建省', '泉州市'): ('泉州市', '泉州市，简称“鲤”，别名刺桐城、温陵，福建省辖地级市，厦漳泉都市圈城市。地处福建省东南部沿海，北承福州、莆田，南接厦门，东望台湾，西毗漳州、龙岩、三明。泉州市依山面海，地形以山地、丘陵为主，地势西北高东南低。属亚热带海洋性季风气候，光热充足，雨量充沛，温暖湿润。'),
    ('福建省', '漳州市'): ('漳州市', '漳州市，福建省辖地级市，厦漳泉都市圈城市，位于福建省南部，东邻厦门市集美区，北与龙岩市漳平、永定等市县毗连，西与广东省梅州市大埔县、潮州市饶平县交界，东南与台湾省隔海相望。'),
    ('福建省', '福州市'): ('福州市', '福州市，简称“榕”，别称榕城，古称闽都，福建省辖地级市、省会、福州都市圈核心城市，Ⅰ型大城市，地处福建省中部东端，东临台湾海峡，地貌属典型的河口盆地，地形以山地、丘陵为主，属典型的亚热带季风气候，温暖湿润，四季常青，阳光充足，雨量充沛。'),
    ('福建省', '莆田市'): ('莆田市', '莆田市，福建省辖地级市，古称兴化、又称“兴安”、“莆阳”、“莆仙”，位于福建沿海中部，地处北纬24°59′—25°46′，东经118°27′—119°56′之间。'),
    ('福建省', '龙岩市'): ('龙岩市', '龙岩市是中华人民共和国福建省下辖的地级市，是国家客家文化生态保护实验区，位于福建省西南部。地处武夷山脉南段东麓，境内多为低山丘陵区。'),
    ('西藏自治区', '山南市'): ('山南市', '山南市，史称“雅砻”，方言是卫藏方言区是中国西藏自治区下辖地级市。位于东经90°14"至94°22"、北纬27°08"至29°47"之间，地处青藏高原冈底斯山至念青唐古拉山脉以南的雅鲁藏布江中下游，北接西藏首府拉萨市，西与日喀则市毗邻，东与林芝市相连，南与印度、不丹两国接壤。'),
    ('西藏自治区', '拉萨市'): ('拉萨市', '拉萨市，别称逻些、日光城，是西藏自治区辖地级市、首府，地处中国西南地区、西藏高原中部、喜马拉雅山脉北侧、雅鲁藏布江支流拉萨河中游河谷平原，地理坐标为东经91°06′，北纬29°36′。'),
    ('西藏自治区', '日喀则市'): ('日喀则市', '日喀则市（藏语：གཞིས་ཀ་རྩེ་གྲོང་ཁྱེར），中国西藏自治区下辖地级市，地处中华人民共和国西南边陲，青藏高原西南部，西衔阿里地区、北靠那曲市、东邻拉萨市与山南市，外与尼泊尔、不丹、印度等国接壤；南北地势较高，其间为藏南高原和雅鲁藏布江流域。'),
    ('西藏自治区', '昌都市'): ('昌都市', '昌都市（藏语：ཆབ་མདོ་གྲོང་ཁྱེར），西藏自治区辖地级市，古称“康”或“客木”，别称康巴、藏东明珠，位于西藏自治区东部、澜沧江上游，地处三河一江地区（昂曲、扎曲、色曲、澜沧江），是西藏自治区的东大门，属高原亚温带亚湿润气候，西北部、北部严寒干燥，东南部温和湿润，日照时间长，干湿分明。'),
    ('西藏自治区', '林芝市'): ('林芝市', '林芝市，是中国西藏自治区下辖地级市，古称“工布”，藏语音译为“尼池”，寓意为“太阳宝座”，地处西藏东南部，素有“西藏江南”、“雪域明珠”等称号。'),
    ('西藏自治区', '那曲市'): ('那曲市', '那曲市，别称黑河，是中国西藏自治区下辖地级市，地处西藏自治区北部，青藏高原腹地，与新疆维吾尔自治区和青海省交界，东邻昌都市，南接拉萨市、日喀则市、林芝市，西与阿里地区相连，属亚寒带气候区，海拔较高，高寒缺氧。'),
    ('西藏自治区', '阿里地区'): ('阿里地区', '阿里地区，西藏自治区辖地区，古称“羊同”“纳里”“俄力思”，位于中国西南边陲、西藏自治区西部、青藏高原北部（羌塘高原），北接新疆维吾尔自治区和田地区、巴音郭楞蒙古自治州，东临那曲市、东南依日喀则市，西南和西部与尼泊尔、印度、克什米尔为界。'),
    ('贵州省', '六盘水市'): ('六盘水市', '六盘水市，别称中国凉都，是中国贵州省下辖地级市，地处黔西乌蒙山区，滇、黔两省接合部，东邻安顺市，南连黔西南布依族苗族自治州，西接云南省曲靖市，北毗毕节市，大地构造属扬子准地台上扬子台褶带，属亚热带季风湿润气候区。'),
    ('贵州省', '安顺市'): ('安顺市', '安顺市，中国贵州省下辖地级市，地处贵州省中西部，地处长江水系乌江流域和珠江水系北盘江流域的分水岭地带，形成中部高、南北低；西北高、东南低的地势，是世界上典型的喀斯特地貌集中地区，属典型的高原型湿润亚热带季风气候。'),
    ('贵州省', '毕节市'): ('毕节市', '毕节市，贵州省辖地级市，位于贵州省西北部，介于北纬26°21′~27°46′，东经103°36′~106°43′之间。'),
    ('贵州省', '贵阳市'): ('贵阳市', '贵阳市，简称“筑”，别称林城、筑城，贵州省辖地级市、省会、Ⅰ型大城市，位于贵州省中部，北部和西部分别与遵义市和毕节市接壤，东部及南部与黔南布依族苗族自治州相邻，西南部与安顺市毗连，属于亚热带湿润气候，地处云贵高原黔中山原丘陵中部，总体地势西南高、东北低，四季分明、温度适宜、降水充沛，主要有南明河、濛江等河流，以及红枫湖、观山湖等人工湖。'),
    ('贵州省', '遵义市'): ('遵义市', '遵义市，简称“遵”，古称播州，贵州省辖地级市，Ⅱ型大城市，地处中国西南地区、贵州省北部，南临贵阳市，北倚重庆市，西接四川省，地形起伏大，地貌类型复杂，属于中亚热带高原湿润季风区，一年四季分明，雨热同季。'),
    ('贵州省', '铜仁市'): ('铜仁市', '铜仁市，贵州省辖地级市，位于贵州省东北部，武陵山区腹地，东邻湖南省怀化市，北与重庆市接壤，西北高，东南低，全境以山地为主，大多数地域属中亚热带季风湿润气候区。'),
    ('贵州省', '黔东南苗族侗族自治州'): ('黔东南苗族侗族自治州', '黔东南苗族侗族自治州，贵州省辖自治州，位于贵州省东南部，东邻湖南省，南接广西壮族自治区，处在云贵高原与湘桂丘陵盆地过渡区，地势西、南、北高而东低，涵盖中山、低中山、低山、丘陵、盆地等地貌，海拔多在500～1000米，属亚热带湿润季风气候。境内有983条河流，以清水江、㵲阳河、都柳江为主干，呈树枝状分布。'),
    ('贵州省', '黔南布依族苗族自治州'): ('黔南布依族苗族自治州', '黔南布依族苗族自治州，简称“黔南州”，贵州省辖自治州，位于贵州省中南部，东与黔东南苗族侗族自治州相连，南与广西壮族自治区毗邻，西与安顺市、黔西南布依族苗族自治州接壤，北靠省会贵阳市；处于贵州高原向广西丘陵过渡的斜坡地带，地势北高南低，地处东亚季风区。'),
    ('贵州省', '黔西南布依族苗族自治州'): ('黔西南布依族苗族自治州', '黔西南布依族苗族自治州，简称“黔西南州”，贵州省辖自治州，首府驻兴义市，位于云南、广西、贵州三省（区）结合部。贵州省西南部，珠江上游，云贵高原东南端。'),
    ('辽宁省', '丹东市'): ('丹东市', '丹东市，古称安东，是辽宁省辖地级市，地处辽宁省东南部，东与朝鲜的新义州隔江相望，南临黄海，西接鞍山，西南与大连毗邻，北与本溪接壤，地势由东北向西南逐渐降低，属暖温带湿润季风气候区。'),
    ('辽宁省', '大连市'): ('大连市', '大连市，别称滨城、浪漫之都，辽宁省辖地级市、副省级市、计划单列市、特大城市，位于中国东北地区最南端，三面环海，东濒黄海，西临渤海，南与山东半岛隔海相望，北依东北平原，地处北半球暖温带地区，属于具有海洋性特点的温带季风气候。全市地貌以山地丘陵为主，平原低地少，地形北高南低，北宽南窄。'),
    ('辽宁省', '抚顺市'): ('抚顺市', '抚顺市，辽宁省辖地级市，别称中国煤都，位于辽宁东部，东与吉林省接壤，西接沈阳市，北与铁岭市毗邻，南与本溪市相望，地处长白山余脉，市区位于浑河冲积平原上，三面环山；呈东南高、西北低之势，位于中温带，属温带季风气候。'),
    ('辽宁省', '朝阳市'): ('朝阳市', '朝阳市，古称龙城、兴中，辽宁省辖地级市，位于辽宁省西北部，地势为北及北西、西南偏高，向东变低，处在北温带大陆性季风气候区。'),
    ('辽宁省', '本溪市'): ('本溪市', '本溪市，是中国辽宁省下辖地级市，国务院批复确定的辽宁省东部的中心城市，位于辽宁省东南部，属中温带湿润气候区，四季分明。'),
    ('辽宁省', '沈阳市'): ('沈阳市', '沈阳，别称盛京、奉天，辽宁省省会、副省级市、特大城市、沈阳都市圈核心城市，国务院批复确定的东北亚国际化中心城市、国家历史文化名城、国际性综合交通枢纽城市，全国先进制造业基地、东北现代服务业中心、区域性科技创新高地。沈阳地处东北地区南部、辽宁中部。'),
    ('辽宁省', '盘锦市'): ('盘锦市', '盘锦市，辽宁省辖地级市，别称鹤乡、油城、湿地之都，盘锦位于辽宁省西南部，地处辽河三角洲中心地带、辽河入海口处，地势平坦，多水无山，是中国最北端的海岸线，地处北温带，属暖温带大陆性半湿润季风气候。四季分明，雨热同季，干冷同期，温度适宜，光照充裕。'),
    ('辽宁省', '营口市'): ('营口市', '营口市，是中国辽宁省下辖地级市，辽宁沿海经济带重要的港口城市，地处中国东北地区南部、辽东半岛中枢，渤海东岸，大辽河入海口处。'),
    ('辽宁省', '葫芦岛市'): ('葫芦岛市', '葫芦岛市，辽宁省辖地级市，原称锦西，地处东北地区西南部、辽宁省西部沿海，属北温带大陆性季风气候，依山傍海，地势自西北向东南逐渐降低；东与锦州市为邻，西与秦皇岛山海关区毗连，南临渤海湾，北与朝阳市接壤。'),
    ('辽宁省', '辽阳市'): ('辽阳市', '辽阳市，古称襄平、辽东城，辽宁省辖地级市，地处中国东北地区、辽宁中部，构成了东南高，西北低的同向倾斜缓降地势，因地貌形态差异，其气候特征亦各不相同。'),
    ('辽宁省', '铁岭市'): ('铁岭市', '铁岭市，古称银州，辽宁省辖地级市，地处辽宁省北部，松辽平原中部，地势大体是东高中低、北高南低，属温带大陆性季风气候，南与沈阳市和抚顺市毗邻，北与四平市相连，东与清原满族自治县、辽源市接壤，西与法库县、康平县及通辽市为邻。'),
    ('辽宁省', '锦州市'): ('锦州市', '锦州市，辽宁省辖地级市，地处欧亚大陆东部，中国东北地区、辽宁西南部、渤海北岸、辽西走廊东部，境内山脉连绵起伏，地势特征是西北高，东南低，属暖温带半湿润气候。'),
    ('辽宁省', '阜新市'): ('阜新市', '阜新市，辽宁省辖地级市，位于东北地区南部、辽宁西北部的内蒙古高原和辽河平原的中间过渡带，全境呈现长矩形，地势西高东低，属北温带半干旱大陆性季风气候。'),
    ('辽宁省', '鞍山市'): ('鞍山市', '鞍山市，辽宁省辖地级市，地处辽东半岛几何中心，地势东南高西北低，自东南向西北倾斜，属暖温带大陆性季风气候区，四季分明，雨热同期，干冷同季，降水充沛，温度适宜，光照丰富。'),
    ('重庆市', '重庆市'): ('重庆市', '重庆市，简称“渝”，别称山城、江城，是中华人民共和国直辖市、超大城市，国家中心城市，是复合型城市，以主城区为依托，大、中、小城市有机结合的组团式、层级式现代城市群，地处中国西南地区、长江上游，东邻湖北省、湖南省，南接贵州省，西靠四川省，北连陕西省以及四川省，地貌以山地、丘陵为主。属亚热带季风性湿润气候，长江干流在境内流程665千米。'),
    ('陕西省', '咸阳市'): ('咸阳市', '咸阳市，中国陕西省下辖地级市，别称秦都、渭城，地处陕西省关中平原中部，是中国大地原点所在地，中国版图的几何中心。位于东经107°38′至109°10′、北纬34°9′至35°34′之间，东与铜川市、渭南市为邻，西与宝鸡市接壤，北同甘肃省庆阳市、平凉市毗连，南接西安市。'),
    ('陕西省', '商洛市'): ('商洛市', '商洛市，别称鹤城、上洛、商州。陕西省辖地级市，位于陕西省东南部，秦岭南麓，与鄂豫两省交界。东与河南省的灵宝市、卢氏县、西峡县、淅川县接壤；南与湖北省的十堰市郧阳区、郧西县相邻；西、西南与陕西省安康市的汉滨区、宁陕县、旬阳市和西安市的长安区、蓝田县毗邻；北与陕西省渭南市的华州区、潼关县、华阴市相连。'),
    ('陕西省', '安康市'): ('安康市', '安康市，陕西省辖地级市，位于陕西省东南部，居川、陕、鄂、渝交接部，位于东经108°00′58″～110°12′，北纬31°42′24″～33°50′34″之间。'),
    ('陕西省', '宝鸡市'): ('宝鸡市', '宝鸡市，陕西省辖地级市，曾称陈仓、雍州、雍城、周原、西虢、西岐、岐邑、岐阳、西府、阳平、凤翔等，地处关中平原西部，嘉陵江源，东连咸阳和杨凌示范区，南接汉中，西北与甘肃省天水、平凉毗邻。秦岭南屏，渭水中流，关陇西阻北横，渭北沃野平原。属暖温带半湿润气候区，冷暖干湿，四季分明。'),
    ('陕西省', '延安市'): ('延安市', '延安市，简称“延”，陕西省下辖地级市、省域副中心城市，位于陕西省北部，北连榆林，南接关中咸阳、铜川、渭南三市，东隔黄河与山西省临汾、吕梁市相望，西邻甘肃省庆阳市。'),
    ('陕西省', '榆林市'): ('榆林市', '榆林市，别名“驼城”，中国陕西省地级市，省域副中心城市，位于陕西省北部、黄河中游西岸，北部和西北部与内蒙古自治区鄂尔多斯市相接，西部、西南部与宁夏回族自治区盐池县以及甘肃省庆阳市部分地区相连，南部接延安市，东部以黄河为主要省界与山西省忻州市、吕梁市相望。'),
    ('陕西省', '汉中市'): ('汉中市', '汉中市，简称“汉”，是中国陕西省下辖地级市，位于陕西省西南部，东与安康市接壤，西与甘肃省陇南市相邻，南与四川省广元市、巴中市相连，北与宝鸡市、西安市毗连。市辖区。'),
    ('陕西省', '渭南市'): ('渭南市', '渭南市，是陕西省辖地级市，古称下邽、莲勺，位于关中平原东部，陕西省东部，地势以渭河为轴线，形成南北两山、两塬和中部平川五大地貌类型区，属温带季风气候。'),
    ('陕西省', '西安市'): ('西安市', '西安市，别名长安、镐京，陕西省省会、副省级市、特大城市，西安都市圈核心城市。地处陕西关中平原腹地，东临黄河、南据秦岭山脉。市境地势南高北低，地形以平原、山地为主，属暖温带半湿润大陆性季风气候，渭、泾、沣、涝、潏、滈、浐、灞穿流于西安城四周，属于黄河水系。'),
    ('陕西省', '铜川市'): ('铜川市', '铜川市，别称同官，是陕西省辖地级市，地处西北地区东部、陕西中部、关中盆地和陕北高原的交接地带，属温带季风气候。'),
    ('青海省', '果洛藏族自治州'): ('果洛藏族自治州', '果洛藏族自治州，青海省辖自治州，简称“果洛州”，位于青海省东南部，地处青藏高原腹地、黄河源头，东临甘肃省甘南藏族自治州和青海省黄南藏族自治州，南接四川省阿坝自治州和甘孜藏族自治州，西与青海省玉树藏族自治州毗连，北和青海省海西蒙古族藏族自治州、海南藏族自治州相依。'),
    ('青海省', '海东市'): ('海东市', '海东市，青海省辖地级市，因位于青海湖以东而得名，位于青藏高原东北部，属半干旱大陆性气候。'),
    ('青海省', '海北藏族自治州'): ('海北藏族自治州', '海北藏族自治州，简称“海北州”，青海省辖自治州，位于青海省东北部，境内祁连山系地处中国地势第三台阶，位于青藏高原东北部，黄土高原西缘。气候属高原大陆性气候，其特点：寒冷期长，温凉期短，光照充足，太阳辐射强。'),
    ('青海省', '海南藏族自治州'): ('海南藏族自治州', '海南藏族自治州，简称“海南州”，隶属于青海省，首府驻共和县，是青海的8个地级行政区之一，东与海东市和黄南藏族自治州毗连，西与海西蒙古族藏族自治州接壤，南与果洛藏族自治州为邻，北隔青海湖与海北藏族自治州相望境内地形以山地为主，四周环山，盆地居中，属典型的高原大陆性气候。'),
    ('青海省', '海西蒙古族藏族自治州'): ('海西蒙古族藏族自治州', '海西蒙古族藏族自治州，简称“海西州”，青海省辖自治州，州府驻德令哈市，地处青藏高原北部、青海省西部。'),
    ('青海省', '玉树藏族自治州'): ('玉树藏族自治州', '玉树藏族自治州（藏语名：ཡུལ་ཤུལ་བོད་རིགས་རང་སྐྱོང་ཁུལ།），青海省辖自治州，简称“玉树州”，首府驻玉树市，藏语意为“遗址”；地势南北高、中间低，西高东低；属典型的高寒性气候。全州。'),
    ('青海省', '西宁市'): ('西宁市', "西宁市，古称青唐城、西平郡、鄯州，别名夏都，青海省下辖地级市、省会，青海省的政治、经济、科教、文化、交通和通讯中心，地处中国西北地区、青海省东部、湟水中游河谷盆地，地理坐标介于东经100°52'-101°54'，北纬36°13'-37°28'之间，地势西南高、东北低，四周群山环抱，湟水河穿城而过，属大陆性高原半干旱气候，气候宜人。"),
    ('青海省', '黄南藏族自治州'): ('黄南藏族自治州', '黄南藏族自治州，简称“黄南州”，青海省辖自治州，首府驻同仁市。位于青海省东南部九曲黄河第一弯，东北部与海东市化隆回族自治县、循化撒拉族自治县为邻，东南部与甘肃省甘南藏族自治州夏河、碌曲、玛曲三县接壤，西北西南部分别与海南藏族自治州贵德、贵南、同德三县以及果洛藏族自治州玛沁县相接。地势南高北低，属高原大陆性气候。全州。'),
    ('香港特别行政区', '香港特别行政区'): ('香港特别行政区', '香港特别行政区，简称“港”，位于中国南部、珠江口以东，西与澳门隔海相望，北与深圳相邻，南临珠海万山群岛，区域范围包括香港岛、九龙、新界和周围262个岛屿。'),
    ('黑龙江省', '七台河市'): ('七台河市', '七台河市，黑龙江省下辖地级市，地处中国东北地区、黑龙江省东部，佳木斯市南侧，完达山山脉西端。'),
    ('黑龙江省', '伊春市'): ('伊春市', '伊春市，是黑龙江省下辖地级市，是国务院批复确定的中国北方重要的生态旅游城市和黑龙江省东北部中心城市。伊春市位于黑龙江省东北部，北纬46°28′~49°26′，东经127°37′~130°46′。'),
    ('黑龙江省', '佳木斯市'): ('佳木斯市', '佳木斯市，中国黑龙江省下辖地级市，地处中国东北地区、黑龙江省东北部，坐落在松花江、黑龙江、乌苏里江汇流的三江平原腹地，北隔黑龙江、东隔乌苏里江，分别与俄罗斯哈巴罗夫斯克和比罗比詹市相望，是中国陆地最东端的地级行政区、最早迎接太阳升起的地方，有“华夏东极”之称。'),
    ('黑龙江省', '双鸭山市'): ('双鸭山市', '双鸭山市，别称煤城，黑龙江省辖地级市，位于黑龙江省东北部，地处完达山北麓、三江平原南缘，东隔乌苏里江与俄罗斯相望，介于东经130°38′57″～134°20′20″，北纬45°47′08″～47°34′28″，境内平原宽广，丘陵起伏，群山绵延。'),
    ('黑龙江省', '哈尔滨市'): ('哈尔滨市', '哈尔滨市，别称“冰城”，位于中国东北地区，黑龙江省西南部，黑龙江省省会、副省级市、特大城市，是中国东北地区北部政治、经济、文化中心，也是哈长城市群核心城市。'),
    ('黑龙江省', '大兴安岭地区'): ('大兴安岭地区', '大兴安岭地区，黑龙江省辖地区，是中国最北、纬度最高的地级行政区，地处黑龙江省西北部、内蒙古自治区东北部，大兴安岭山脉东北坡，辖区。'),
    ('黑龙江省', '大庆市'): ('大庆市', '大庆市，是中国黑龙江省下辖地级市，国务院批复确定的黑龙江中西部重要的中心城市、中国重要的石油生产和石化工业基地，地处嫩江平原北部，地貌类型属于松花江、嫩江冲积一级阶地，属北温带大陆性季风气候区内。'),
    ('黑龙江省', '牡丹江市'): ('牡丹江市', '牡丹江市，别称雪城，是中国黑龙江省下辖地级市，位于黑龙江省的东南部，长白山的北部，是国务院批复确定的黑龙江省东南部重要的中心城市和风景旅游城市，省政府批复的中国东北地区的开放门户，面向俄罗斯和东北亚的交通枢纽城市，对俄合作示范城市。牡丹江市共辖4个市辖区、1个县，代管5个县级市。'),
    ('黑龙江省', '绥化市'): ('绥化市', "绥化市，别称“北团林子”，是中国黑龙江省下辖地级市，位于黑龙江省中部，松嫩平原的呼兰河流域，地理位置东经124°13′至128°30'，北纬45°3′至48°02'之间，海拔高度为135—247米；东接林都伊春，南临省会哈尔滨，西靠油城大庆，北依口岸黑河，西北连鹤城齐齐哈尔。"),
    ('黑龙江省', '鸡西市'): ('鸡西市', '鸡西市，中国黑龙江省辖地级市，因市区地处鸡冠山西麓而得名，位于黑龙江省东南部，地处世界三大黑土带之一的三江平原腹地。'),
    ('黑龙江省', '鹤岗市'): ('鹤岗市', '鹤岗市，是中国黑龙江省下辖地级市，位于黑龙江省东北部，东至松花江与同江市一水相连，西邻伊春市，南与佳木斯市汤原县接壤，北部以黑龙江主航道为界与俄罗斯隔江相望。幅员。'),
    ('黑龙江省', '黑河市'): ('黑河市', '黑河市，是中国黑龙江省下辖地级市，古称瑷珲，位于黑龙江省北部，地处大兴安岭东端，小兴安岭北部，境内群山连绵起伏，属中温带大陆性季风气候。'),
    ('黑龙江省', '齐齐哈尔市'): ('齐齐哈尔市', '齐齐哈尔市，别称鹤城、卜奎，是中国黑龙江省下辖地级市，地处中国东北地区，东北松嫩平原，在黑龙江、吉林、内蒙古三省区交汇处，东临大庆市和绥化市，南接吉林省白城市，西靠内蒙古呼伦贝尔市、兴安盟，北与黑河市和大兴安岭地区接壤。'),
}
